window.HARDTRP.receive("151968",[[151969,"2026-08-11T07:02:54",9,"Начало темы.\n\n@QURTZZ — Дм этой темы.",151968,null],[152998,"2026-08-11T15:09:18",31,"@STR_AllXSeeV\n@sweetkittywitch\n@cirson\n@FelixFadeev\n\nДобро пожаловать на квест. Мне нужно какое то время чтобы ознакомиться с вашими анкетами, возможно что то я использую в истории. Так что начнем либо через пару-тройку часов, либо уже завтра. Еще раз напомню, это песочница, у вас будет задача и мы начнем с ее получения, го затем вы вольны делать что хотите. В рамках разумного конечно, становится бомжами убийцами не стоит)) и не стесняйтесь меня одергивать, я только учусь водить и стараюсь реагировать на критику адекватно. Критикой, если что, не явлелся грубость и требование что то переиграть задним числом, это не круто. Я открыт к вашим идеям, и ценю креативные решения, за них можете получить вдохновение",151968,null],[153001,"2026-08-11T15:10:36",31,"Если у кого т еть вопросы, давайте обсудим из на берегу так сказать",151968,null],[153005,"2026-08-11T15:11:23",31,"Локация, вдохновлена итальянскими средневековыми городами республиками",151968,null],[153015,"2026-08-11T15:14:31",31,"Да, кстати, я исхожу из того что все ваши персонажи незнакомы и очень вероятно что я дам каждому какой то квест приквел, чтобы довести вас до стартовой точки. Для Эли уже в принципе есть, плтому что я знал о ее персе заранее. По остальным мне нужно будет еще подумать и что то согласовать",151968,null],[153019,"2026-08-11T15:15:28",31,"Скиньте сюда пожалуйста ваши анкеты, чтобы я их не искал в большом чате и я пойду читать)",151968,null],[153020,"2026-08-11T15:15:32",47,"/я в Веспирали работаю. Гробовщику помогаю. Там если что караванами ходить могу",151968,null],[153022,"2026-08-11T15:16:14",38,"// Ссылки или прям текстом?",153019,null],[153023,"2026-08-11T15:16:21",31,"Ссылку",153022,null],[153026,"2026-08-11T15:16:41",38,"https://t.me/c/3239766844/5443",151968,null],[153027,"2026-08-11T15:16:48",41,"( опа",153020,null],[153028,"2026-08-11T15:16:50",47,"https://t.me/c/3239766844/2501",151968,null],[153029,"2026-08-11T15:16:59",41,"( только я вроде не в веспирали",151968,null],[153030,"2026-08-11T15:17:03",31,"О, прикольно. У нас Эля тоже гробокопатель))/",153020,null],[153031,"2026-08-11T15:17:14",47,"Понял) /",151968,null],[153032,"2026-08-11T15:17:23",47,"/а я ещё и по совмещению бард",151968,null],[153052,"2026-08-11T15:19:35",41,"Отпевающий*",153032,null],[153069,"2026-08-11T15:22:23",47,"Как ни странно, нет. Она у меня златоустка/",153052,null],[153096,"2026-08-11T15:26:14",31,"Хмм, раз вы обе имеете отношение к кладбищу, то общий страт для вас наверное возможен. Чуток перепишу. Вообще забавно, писал думал что для плутов, а у меня тут бард, паладин, волшебник и чародей)/",151968,null],[153099,"2026-08-11T15:26:36",31,"Хотя, и оракул в названии, судьба/",151968,null],[153124,"2026-08-11T15:31:19",47,"/ну у меня компетенции есть",151968,null],[153125,"2026-08-11T15:31:44",31,"Да ты тут вообще главный дядька, пардон, тетка)/",151968,null],[153126,"2026-08-11T15:32:27",47,"Всм?",151968,null],[153127,"2026-08-11T15:32:42",31,"Ну Кейтлин это разве не женское имя?",153126,null],[153130,"2026-08-11T15:37:46",47,"/почему главная",153127,null],[153131,"2026-08-11T15:38:29",31,"Третий левел. Остальные нулевые",153130,null],[153132,"2026-08-11T15:38:39",47,"/пон. Жестить незя",151968,null],[153133,"2026-08-11T15:38:49",47,"В принципе, она у меня по социалке в основном",151968,null],[153134,"2026-08-11T15:39:22",31,"Не будет тут жести. Если сами не начнёте.",151968,null],[153135,"2026-08-11T15:40:21",47,"Не начну",151968,null],[153136,"2026-08-11T15:41:00",31,"Так, если никто не против я дя начала накидаю квест для для Феликса и Дениса, чародея и обывателя волшебника. Думаю часок мне подвбится, чисто им познакомится. А потом уже устрою встречу на кладбище для Эли и Миши. Сорри что пока без имен персонажей, мне их еще запомнить нужно/",151968,null],[153139,"2026-08-11T15:53:29",41,"( ваще збс плуты",153096,null],[153140,"2026-08-11T15:54:21",31,"@FelixFadeev @STR_AllXSeeV будьте готовы стартовать через час? В 14-00 по Москве?",151968,null],[153141,"2026-08-11T15:55:06",38,"// В москве через час будет 17",153140,null],[153142,"2026-08-11T16:03:07",31,"Сорян, математика это мое слабое место)) значит в 17-00))",153141,null],[153143,"2026-08-11T16:04:25",41,"Аэ?",153140,null],[153144,"2026-08-11T16:04:35",41,"Ок",151968,null],[153156,"2026-08-11T16:25:59",55,"ок ждём",151968,null],[153295,"2026-08-11T16:59:31",31,"@STR_AllXSeeV @FelixFadeev \n\nВаше путешествие в город Вальдория наконец то заканчивается, и корабль, пассажирами которого вы были две недели, входит в порт. Я не знаю, успели ли вы познакомиться в пути, но сейчас у вас будет время, так как очередь перед портовым чиновником движется довольно медленно. Ну а затем вас ждет Вальдория, громадный город, полный возможностей. И только вы знаете, для чего прибыли сюда, для дела, в поисках приключений или знаний.\n\nИтак, вы находитесь в здании портовой конторы по делам прибывших и стоите в очереди к регистратору. Вокруг куча людей и нелюдей, все что то обсуждают, стоят планы, делятся слухами. А что делаете вы?",151968,null],[153298,"2026-08-11T17:03:16",38,"Лени сразу же достал записную книжку и перо с чернилами начав писать все что видит.\n\"Я наконец-то приехал сюда! Я так рад! Боже, спасибо мастеру за такую возможность! Вместе с этим могу сказать, что тут довольно людно, но все равно интересно! Надеюсь тут есть какие-нибудь тайны или приключения!\"\n На этом Лени закрыл свою книжку и осмотревшись решил посмотреть сколько человек и не только в очереди до него.",151968,null],[153306,"2026-08-11T17:07:18",31,"Небольшая комнатка забита, тут в обще сложности человек 20, перед тобой в очереди что то около 5 человек, на каждого у регистратора уходит минут по 10, но бывают и те, кто проскакивает моментально",153298,null],[153316,"2026-08-11T17:12:05",55,"Вейн стоял позади восторженного парня с книжкой. Мягко улыбнулся, хотя сам еле сдерживал свой восторг. Наконец-то новое место! Новые люди и приключения! Да, хорошо он имел хоть какую-то сдержанность, иначе бы заболтал окружающих до смерти. Он тоже посмотрел на очередь. Понимая , что ждать ну в целом терпимо осталось, он стал насвистывать мелодию песни , которую слышал от моряка на корабле. В итоге он решил подойти с боку к парню впереди. \n– А можно поинтересоваться, что ты с таким восторгом записываешь?",153298,null],[153339,"2026-08-11T17:16:35",38,"\"Мда... И почему так скучно...\"\n Лени начал качаться с пяток на носки и услышав слова человека сзади развернулся корпусом, но ногами также прямо и сказал.\n— Секрет, сэр. Зачем раскрывать тайну или узнавать будущее? Это же убивает весь энтузиазм и мотивацию увидеть это! Так что если вы захотите узнать что же было написано можете узнать года через... два или три? В общем, когда я стану писателем или рассказчиком.\n На этом Лени развернулся обратно и продолжил качаться на ногах.",151968,null],[153348,"2026-08-11T17:19:18",31,"Очередь продвигается, очередной посетитель проскочил крайне быстро",151968,null],[153364,"2026-08-11T17:22:42",55,"– Эй, эй, а может ну это очередь и пролезем по быстрому?\nШепнул эльф , как оказалось, начинающему писателю. Или может историку. Кто знает. \n– Один конечно быстро проскочил, но мы не знаем, сколько могут проторчать там остальные. Неужели не хотите быстрее увидеть город?\nПродолжил подбивать парень впереди стоящего.",153339,null],[153367,"2026-08-11T17:25:47",38,"— А зачем? У меня и вас еще много времени впереди, а если вы хотите, то можем поменяться в очереди.\n Ответил Лени и немного подумав сказал.\n— Да и мне некуда спешить, все равно нужно проживать каждый момент по полной и очередь очень хороший пример, а то в книгах иногда полностью убирают момент с очередями и мне нужен опыт.",153364,null],[153371,"2026-08-11T17:27:41",31,"//мне нравится, пока вас представляю чем то типа ангела и демона на плечах)/",151968,null],[153372,"2026-08-11T17:28:08",38,"// Два демона",153371,null],[153373,"2026-08-11T17:28:17",38,"// Просто один Лень",151968,null],[153396,"2026-08-11T17:32:30",31,"Регистратор отпускает очередного посетителя, встает, и заявляет:\n\n-обеденный перерыв, вернусь черкз час",151968,null],[153405,"2026-08-11T17:34:09",38,"// Пизда! Тут всем пизда!",153396,null],[153406,"2026-08-11T17:34:20",38,"// Я щас убью всех!",151968,null],[153413,"2026-08-11T17:37:28",31,"По толпе проносится ропот, слышны угрозы в адрес регистратора и его ближайших родственников",151968,null],[153414,"2026-08-11T17:39:24",55,"– ПЕРЕРЫВ?! ЧЕГО?!\nМгновенно вспылил остроухий. Мало того , что бумагамаратель впереди не уговариваемый, так ещё и этим приспичило идти жрать целый час. \n– Они там кабана сожрать удумали?!\nА глазки-то засветились, каким бы жизнь общине не пыталась делать эладрина, он всё равно останется капризным.",151968,null],[153415,"2026-08-11T17:39:51",41,"( летний?",153414,null],[153416,"2026-08-11T17:39:58",38,"Слушая часть криков Лени сказал себе под нос.\n— Да ладно... Я готов сказать, что этот регистратор точно получит в лицо... И я говорю не за себя, а за тех, кто его поймают...",151968,null],[153417,"2026-08-11T17:40:35",55,"/ ну да. По крайней мере сейчас. К тому же душа феникса. Гремучая смесь для характера",153415,null],[153418,"2026-08-11T17:40:52",31,"- да, правильно, какой к херам перерыв\n\nТолпа поддерживает возмущение Вейна\n\nМужик стоявший в очереди первым подскакивает к чиновнику и пытается схватить того за грудки",151968,null],[153421,"2026-08-11T17:42:21",38,"— Воу... Не думал, что я угадаю такое...\n На этом Лени решил понаблюдать чуть больше",151968,null],[153422,"2026-08-11T17:42:25",41,"( как бы я хотела оказаться Рядом с ними",151968,null],[153423,"2026-08-11T17:42:54",31,"Мне уже интересно как вы будете допросы вести))) ну в основном квесте))//",151968,null],[153424,"2026-08-11T17:43:21",41,"( пустишь меня? С бардом пересечемся",153423,null],[153425,"2026-08-11T17:43:53",31,"Ну давай, бог с тобой, ты тоже в очереди была/",153424,null],[153426,"2026-08-11T17:44:56",31,"Регистратор визжит:\n\n- вас много а я один, у меня кчть право на перерыв!",151968,null],[153427,"2026-08-11T17:45:05",41,"— ТИШИНА! \n\nразлался тяжелый и грубый женский голос, рука в мозолях, не характерная для девушки поднялась вверх.",151968,null],[153430,"2026-08-11T17:45:34",31,"Выступление/",153427,null],[153431,"2026-08-11T17:45:41",31,"Или что то подобное/",151968,null],[153434,"2026-08-11T17:46:13",41,"— Мужчина перед вами ваш слуга, и имеет право уйти тогда, Когда работа ему это выписывает. Так и вы должны держать себя в руках! Что вы себе позволяете?! Как малые дети...",151968,null],[153435,"2026-08-11T17:46:45",41,"/r d20+0",151968,null],[153437,"2026-08-11T17:46:51",41,"( ы",151968,null],[153439,"2026-08-11T17:46:58",41,"( ща тапками закидают",151968,null],[153440,"2026-08-11T17:46:58",31,"Мужик не впечатлен/",151968,null],[153441,"2026-08-11T17:47:12",31,"Он похоже тебя и не услышал за гомоном толпы",151968,null],[153442,"2026-08-11T17:47:38",47,"/мне типо тоже вписываться, или пофиг?",151968,null],[153444,"2026-08-11T17:47:46",41,"Мужик который схватил? \n\nИду к нему",151968,null],[153445,"2026-08-11T17:47:50",47,"Мне лично пофиг, могу и позже явиться",151968,null],[153448,"2026-08-11T17:47:53",41,"( ахаха",153442,null],[153449,"2026-08-11T17:47:59",31,"Давай, если хочешь, начнем отсюда все/",153442,null],[153451,"2026-08-11T17:48:07",31,"Мне проще будет/",151968,null],[153454,"2026-08-11T17:48:46",47,"Кейтлин в это время где-то поблизости, через одного человека от эладрина пилочкой подтачивает ногти",151968,null],[153456,"2026-08-11T17:49:10",31,"Подошла, что дальше?",153444,null],[153457,"2026-08-11T17:49:17",47,"Ощущение будто ей всё равно... Абсолютнейше",151968,null],[153458,"2026-08-11T17:49:54",55,"А эльф конечно сначала встрепенулся от крика громогласной дамы, но после подошёл к администратору. \n– Я тебя щас до румяной корочки прожарю!\nГлаза у эладрина засветились ярче, в ладони показалось парочка языков пламени.",151968,null],[153459,"2026-08-11T17:50:25",31,"Убеждение кинь/",153458,null],[153462,"2026-08-11T17:50:38",31,"С преимуществом/",151968,null],[153465,"2026-08-11T17:50:54",38,"// Там есть скамейки или что-то чтобы присесть?",151968,null],[153467,"2026-08-11T17:51:13",31,"Да, конечно, вдоль стен стоят",153465,null],[153468,"2026-08-11T17:51:13",47,"/запугивание",153459,null],[153470,"2026-08-11T17:51:34",47,"/я не говорю чио надо как я говорю, но буду подсказывать, что логичнее... Если не протыв",151968,null],[153472,"2026-08-11T17:51:43",55,"/ так а как рассчитывать щас надо будет? Зотя тут скорее запугивание уже 😂. Очень извиняюсь",153459,null],[153473,"2026-08-11T17:51:43",31,"Или так, да/",153468,null],[153474,"2026-08-11T17:52:03",31,"Не против, я много не знаю/",153470,null],[153475,"2026-08-11T17:52:14",38,"// д20 + модификатор харизмы + модификатор бонуса мастерства если владеешь навыком",153472,null],[153476,"2026-08-11T17:52:41",38,"// кидается через /roll 1d20+0+0 или /r 1d20+0+0",151968,null],[153478,"2026-08-11T17:53:24",55,"/r 1d20+3",151968,null],[153480,"2026-08-11T17:53:28",31,"В твоем случае /roll d20+3",153472,null],[153486,"2026-08-11T17:53:56",41,"( отходила сори",151968,null],[153487,"2026-08-11T17:54:06",38,"— Кошмар...\n Сказал себе под нос Лени и решив подождать затишья подошел к лавочке и сел.\n— Так... А теперь смотрим и записываем...\n Лени начал записывать в свою книжку все действия и немного улыбаться.",151968,null],[153488,"2026-08-11T17:54:10",31,"Можешь еще раз, я преимущество дал, выберем лучший исход/",151968,null],[153491,"2026-08-11T17:54:38",55,"/ мда...",151968,null],[153494,"2026-08-11T17:55:02",31,"Ладно, и первый прокатил, страшный эльф запугал почти удушенного регистратора",151968,null],[153495,"2026-08-11T17:55:06",41,"— Мужчины… терпение ещё никого не убивало. Позвольте регистратору заслуженно отдохнуть",153458,null],[153497,"2026-08-11T17:55:21",31,"- ладно, ладно, я все сделаю, только отпустите...",151968,null],[153502,"2026-08-11T17:55:52",41,"( эх упустила возможность, видимо",151968,null],[153508,"2026-08-11T17:56:23",31,"Регистратор оказывается на свободе и тут же вместо конторки бросается к двери, мгновенно оказываясь за ней",151968,null],[153513,"2026-08-11T17:57:05",31,"Из за двери вы слышите его возбуженный голос и лязг железа, похоже, страже не понравилось нападение на чиновника",151968,null],[153521,"2026-08-11T17:58:41",31,"Дверь открывается, и внутрь входит дюжий стражник, за спиной которого прячется регистратор. Тот в свою очередь тычет пальцем в Вейна и того мужика, что удерживал его у стены",151968,null],[153525,"2026-08-11T17:59:31",41,"— и такое случается… \n\nВздохнула женщина",151968,null],[153526,"2026-08-11T18:00:01",38,"\"Сами напросились... Кстати... Лавка то удобная... Может еще немного посижу...\"\n И на этом Лени даже немного облокотился и полусидя, полулежа продолжил находится на лавке.",151968,null],[153529,"2026-08-11T18:01:20",41,"Девушка будто не при делах присела не далеко от Лени. Взгляд был уставший, возможно от долгой дороги, возможно от бессонной ночи. Кто его знает",151968,null],[153530,"2026-08-11T18:01:27",55,"Эльф сжал кулак и всё же вернулся на своё место. \n– Вот так бы... Э, куда?!\nПотом услышав лязг металла парень сжался. Потом вроде бы выпрямился и тут вышла громадина. \n– Эй, чинуша, чинуша , чего прячешься за амбалом? Я лишь пригрозил , но тебе лично ничего не сделал. И вообще гнев мой праведный!",151968,null],[153532,"2026-08-11T18:01:32",31,"Стражник, обращаясь к мужику и Вейну:\n\n- именем закона города Вальдория вы арестованы за нападение на городского чиновника. Советую не оказывать сопротивления и найти адвоката",151968,null],[153533,"2026-08-11T18:02:00",55,"/ да как успевать...",151968,null],[153535,"2026-08-11T18:02:25",31,"Чинуша пискнул и спрятался за амбала",153530,null],[153538,"2026-08-11T18:03:43",31,"- Боб, вернись ка\n\nРаздался голос из за двери, стражник, заслышав его, вышел и закрыл дверь",151968,null],[153541,"2026-08-11T18:04:19",55,"/ блин. Реально не успеваю ответ переписывать",151968,null],[153554,"2026-08-11T18:05:25",31,"Извини, у меня что-то полет мысли пошел, постараюсь притормозить/",151968,null],[153555,"2026-08-11T18:05:57",31,"Так, стражник за дверью, что то обсуждает, ваши действия)?",151968,null],[153556,"2026-08-11T18:05:58",55,"– А? Чего?\n\nТолько что расхрабрившийся парень впал в ступор и начал остывать. \n\n– Только арестовывать собрались, а тут стоп?\n\nТолько и смог выдать эльф и после присел к парочке писателя и той самой громогласной дамы.",153538,null],[153559,"2026-08-11T18:07:47",31,"Никто больше не реагирует?/",151968,null],[153560,"2026-08-11T18:07:59",38,".",153526,null],[153562,"2026-08-11T18:08:58",31,"Ок, продолжаю/",151968,null],[153563,"2026-08-11T18:09:09",41,"( мы присели",151968,null],[153568,"2026-08-11T18:11:25",31,"Дверь вновь открывается, стражник Боб возвращается:\n\n- уточнив детали обновленной инструкции стражи порта, я обязан отреагировать на жалобу регистратора путём проведения общего опроса свидетелей. Подтверждаете ли вы, здесь собравшиеся, что указанные особы действительно напали на регистратора?",151968,null],[153569,"2026-08-11T18:12:37",38,"— Только мужчина взбесился на регистратора и схватил за воротник, а так ничего не было.\n Немного крикнув сказал Лени и продолжил дальше писать.",153568,null],[153570,"2026-08-11T18:12:42",41,"—... \n\nОна не хотела реагировать. Портить жизнь кому-то явно не в её целях",153568,null],[153576,"2026-08-11T18:15:52",31,"Стражник принял это к сведению, а затем устроил голосование путем поднятия рук. Версия, изложенная Лени нашла подтверждение, и мужика увели в темницу. Через некоторое время появился новый регистратор, который не глядя ни на кого, быстро поставил необходимые печати всем подряд и ретировался. Вы получили право пройти в город и оказались на большой пристанской площади. Город перед вами",153569,null],[153578,"2026-08-11T18:16:21",47,"Ближе подошла Кейтлин с тяжким вздохом выпустив пилочку из рук",151968,null],[153580,"2026-08-11T18:16:59",55,"/ сорри, отходил",151968,null],[153581,"2026-08-11T18:16:59",31,"Хотел всех познакомить, не особо видать вышло)/",151968,null],[153582,"2026-08-11T18:18:02",47,"Она тоже получила это право и вслух высказалась в духе:\n- Если захочешь найти проблемы парень, ищи их не так рьяно - дала совет Кейтлин и огляделась... Вот она сюда приехала зачем? Затем что одна сука спиздила у неё буквально из под рук очень выгодный заказ. Её бы найти...",151968,null],[153583,"2026-08-11T18:18:19",47,"/создай ещё событие, которое заставит нас познакомиться",153581,null],[153584,"2026-08-11T18:18:25",41,"( а мы с Кейтлин вместе приехали",151968,null],[153587,"2026-08-11T18:18:53",55,"// это щас кому?  Я просто но пойму на что реагировать",153582,null],[153592,"2026-08-11T18:19:11",41,"( Элиза возвращалась с другого города где учила могильщиков накладывать грим",151968,null],[153595,"2026-08-11T18:19:21",41,"( Кейт тоже",151968,null],[153597,"2026-08-11T18:19:45",31,"С конференции по косметике девушки прибыли, ясно, жизненно/",151968,null],[153600,"2026-08-11T18:20:17",55,"/ мастер-класс по танатопрактике скорее",151968,null],[153601,"2026-08-11T18:20:25",38,"Лени вздыхает и наконец-то выйдя из комнаты посмотрел на выходящих и ко всему записанному написал.\n\"В итоге мне понравилось... Я бы просидел на той скамейке еще немного... Так о чем я? Теперь я в городе!\"",151968,null],[153611,"2026-08-11T18:21:59",47,"/тебе",153587,null],[153612,"2026-08-11T18:22:13",55,"Вейн посмотрел на обратившуюся к нему девушку. \n– Ну... Ничего с собой поделать не могу. Не контролирую себя вообще. \nОтветил он и радостно посмотрел на свой пропуск. \n– Ура! Можно наконец в город!\nСказал он и зашагал дальше.",153582,null],[153616,"2026-08-11T18:23:31",47,"- От придурок - помахала головой она. Где же тут была резиденция этого долбанного Шалье, тут же она переключилась и начала оглядываться",151968,null],[153617,"2026-08-11T18:23:38",47,"/мастер, лови, ща разбегаться начнём",151968,null],[153618,"2026-08-11T18:23:45",31,"К вам, очевидно новеньким в городе, подбегает стайка мальчишек, каких полно в каждом порту. Они всегда ищут подработку, что то перетащить, что то стащить или что то рассказать, монетизируя свои знания о городе\n\nОт толпы отделяется один, лидер или разведчик, подходит к вам. Остальные прибывшие уже разошлись\n\n- здрасьте, гспда. Вам может помощь какая нужна?",151968,null],[153621,"2026-08-11T18:24:45",38,"Лени заметил их и сказал.\n— О и вам юнцам привет, хотя я сам еще юнец... Так вот, где у вас тут таверна ближайшая?",153618,null],[153623,"2026-08-11T18:24:59",47,"- Малыш, а не сводишь тётю до резиденции Шалье - присев на кортки мило улыбается девушка и если ей дают, гладит малыша по голове. \n Буквально завораживает взглядом...",151968,null],[153628,"2026-08-11T18:25:12",47,"/одного из пацанов",153623,null],[153637,"2026-08-11T18:26:03",31,"- Ну так знамо где, через дорогу жеж. Золотой Марлин, только дорого там\n\n*тыкает пальцем в заведение с какой-то рыбиной на вывески*",153621,null],[153649,"2026-08-11T18:27:08",55,"– Не , мелкие , пожалуй откажусь. Сам не богат. \nОтветил чародей и посмотрел на тут самую девушку, которая влезла со своими комментариями. Потом обратил внимание на указанную таверну. \n– О, туда нам надо!",153618,null],[153651,"2026-08-11T18:27:26",31,"*пацан поплыл*\n\n- я, я не знаю госпожа, простите...\n\n*готов провалится сквозь мостовую*",153623,null],[153652,"2026-08-11T18:27:27",41,"Нас двое кстати *",153623,null],[153653,"2026-08-11T18:28:16",41,"— было бы здорово. Если бы твои друзья провели нас. Я заплачу каждому золотой",153651,null],[153658,"2026-08-11T18:28:56",31,"- мы узнаем и вернемся, госпожа. Вы будете в Марлине?",153653,null],[153660,"2026-08-11T18:29:12",41,"( Марлин это?",151968,null],[153661,"2026-08-11T18:29:20",31,"Таверна/",153660,null],[153662,"2026-08-11T18:29:42",41,"— Марлин... Это таверна? Она в какой стороне?",151968,null],[153664,"2026-08-11T18:30:05",31,"Я выше отвечал. Тут она, через дорогу/",153662,null],[153666,"2026-08-11T18:30:18",41,"( уПС. Сори, отходила",151968,null],[153667,"2026-08-11T18:30:30",38,"Лени улыбнулся и немного поклонившись сказал.\n— Спасибо парни, а за это... Я покажу вам фокус...\nНа этом одежда парня начала меняться на обычный костюм с белой рубашкой и серыми брюками с черной рясой.",151968,null],[153668,"2026-08-11T18:30:52",47,"Кейтлин лишь опять помахала головой и огляделась",151968,null],[153669,"2026-08-11T18:30:54",41,"( я не особо читаю разговор между Лени и Феликсом",151968,null],[153670,"2026-08-11T18:30:55",38,"— Теперь до свидания...\n Лени пошел в сторону таверны",151968,null],[153671,"2026-08-11T18:31:00",47,"Опиши местность пожалуйста мастер. Кратко",151968,null],[153672,"2026-08-11T18:31:05",55,"После этих слов парень направился в таверну.",153649,null],[153673,"2026-08-11T18:31:14",47,"/типо центр города, центральная площадь с фонтанами, или где мы там",151968,null],[153675,"2026-08-11T18:31:19",41,"— Вижу... Да, Мы будем там",151968,null],[153676,"2026-08-11T18:31:38",41,"( мы в порту Наверное?",151968,null],[153677,"2026-08-11T18:31:44",31,"@cirson ты мне хоть скинь в личку, что за Шалье, а то я хз куда вас отправить. Точнее, знаю куда, к квастодвтелю, но мне нужно понимание куда потом/",151968,null],[153678,"2026-08-11T18:31:45",38,"// Тут по факту",153005,null],[153680,"2026-08-11T18:32:11",41,"— идем в золотой Марлин, Кейт. Ты устала, там тебе дадут чего-то освежающего",151968,null],[153683,"2026-08-11T18:33:31",47,"- У меня каждая монета на счёт... Марлин дорого выглядит - слегка недовольно произнесла Кейт",151968,null],[153687,"2026-08-11T18:35:09",47,"/ей надо в ремесленный город",151968,null],[153688,"2026-08-11T18:35:12",41,"— Я попрошу у них только лед и разбавим им наш кофе\n\nОна показала бутылку с бесконечным кофе",153683,null],[153691,"2026-08-11T18:35:55",47,"- Ну ладно, ты меня убедила - приобняла",151968,null],[153693,"2026-08-11T18:37:01",41,"Элиза обняла в ответ и повела подругу в таверну",151968,null],[153696,"2026-08-11T18:38:46",41,"Мы заходим",151968,null],[153697,"2026-08-11T18:39:04",38,"// Щас мастер вернется",151968,null],[153700,"2026-08-11T18:40:29",31,"Таверна встречает вас шумом, запахом рыбы и какого то местного алкоголя. Заведение очевидно неплохое, во всяком случае вы не увидели ни одного пьяного человека, плавающего в луже своих же испражнений, что автоматически добавляет ему очков в ваших глаза. Волей судеб и того самого обеденного перерыва, все столы заняты, кроме одного, в дальнем углу, который словно вас четверых и ждал",151968,null],[153702,"2026-08-11T18:41:50",41,"— Займи нам столик, а я попрошу лед.",151968,null],[153704,"2026-08-11T18:42:21",47,"Присаживаюсь за стол и достаю свою гитару. Начинаю тихо играть мелодию",153702,null],[153705,"2026-08-11T18:42:33",31,"Ребята, просьба, чуток поболтайте и познакомьтесь, мне нужно вас довести до квестодателю, а у меня все пошло не так. Пока обедаете и ждёте пацанов с информацией, успейте познакомится/",151968,null],[153706,"2026-08-11T18:44:24",41,"Она пойдет к бурной стойке, смотря на цену здешних напитков",151968,null],[153708,"2026-08-11T18:44:37",38,"Лени заметил столик и заметив, как туда идет уже одна \"знакомая\" вздохнул и изменил наряд на саван и штаны серых оттенков с небольшой рубашкой под саваном, чтобы иметь рукава до кисти.\n \"Хм... Надо же было в обед приходить...\"\n Парень пошел прямо к трактирщику, или кто там, и сказал.\n— Здраствуйте сэр, можно ли узнать цену у вас?",151968,null],[153710,"2026-08-11T18:45:56",31,"А чего ты хочешь парень, у нас тут много чего подают. Рыбки, или мяса? Или слкжт ты из этих, кто только зелень ест?",153708,null],[153711,"2026-08-11T18:47:10",41,"Элиза видимо подошла к второму бармену. \n\n— Мне нужно два небольших стакана льда и долька апельсина...",151968,null],[153712,"2026-08-11T18:47:26",31,"Цены стандартные\n\n/за стандарт беру днд. СУ/",153706,null],[153713,"2026-08-11T18:47:54",38,"— Мне бы узнать цену обеда и ночлега, если таковой тут есть.",153710,null],[153715,"2026-08-11T18:48:35",55,"Вейн идёт к свободному столику и присаживается. \n– Ну уж нет. Тут явно всё дорогое, но хоть можно отдохнуть. \nПотом он обращает внимание на девушку, которая была от него явно не в восторге после выходки на регистрации. \n– Я извиняюсь за свой концерт сегодня.",153704,null],[153718,"2026-08-11T18:49:37",31,"Кусок мяса и ломоть хлеба за 5 серебряных, крыжка пива еще 5 медных, постой 8 серебряных за ночь",153713,null],[153719,"2026-08-11T18:50:29",31,"Лед по серебрянке, апельсин целико за 5 медяков",153711,null],[153720,"2026-08-11T18:50:48",38,"— А кроме пива что-то еще есть, просто... Мне нету еще возраста для пива...",153718,null],[153723,"2026-08-11T18:51:56",31,"- молока могу налить за 5 медяков, но с соленой рыбой не советую",153720,null],[153724,"2026-08-11T18:53:18",38,"— Ну а кроме молока и пива? Думаю есть что-то еще в меню.",153723,null],[153725,"2026-08-11T18:54:38",31,"Вино есть, вода просто, ну и кофе могу налить, если хочешь",153724,null],[153726,"2026-08-11T18:54:47",41,"Она кладет 1 зм\n\n— без сдачи",153712,null],[153727,"2026-08-11T18:55:13",41,"( ну или могла таки дать одну",151968,null],[153728,"2026-08-11T18:55:23",41,"( лед наверное сложно добыть",151968,null],[153730,"2026-08-11T18:56:11",31,"Так потому он и по Серебрянке, ты переплатила раз так в 12/",151968,null],[153731,"2026-08-11T18:56:30",31,"Весь твой заказ 2,5 серебряных/",151968,null],[153733,"2026-08-11T18:56:50",41,"( во, лучше",151968,null],[153734,"2026-08-11T18:57:11",55,"/ раз богатая , отдай моему скряге",151968,null],[153736,"2026-08-11T18:57:55",31,"Получаешь два стакана льда и апельсин",153726,null],[153738,"2026-08-11T18:58:24",38,"Лени вздохнул оперевшись локтями об стойку и сказал.\n— Тогда мне кофе, мяса с хлебом за 5 серебренных и на одну ночь постой...\n Вместе с этим Лени протянул две золотые.\n— И на сдачу побольше кофе...",153725,null],[153742,"2026-08-11T19:00:36",41,"— Благодарю... \n\nДевушка пойдёт в сторону столика в углу. Нальет себе и Кейт кофе, после выжмет ей и себе апельсиновую дольку",153736,null],[153743,"2026-08-11T19:00:51",31,"Получаешь все указанное и два полных кувшина кофе",153738,null],[153745,"2026-08-11T19:02:17",41,"( кувшина??? Бляяя",151968,null],[153746,"2026-08-11T19:02:26",41,"( не",151968,null],[153747,"2026-08-11T19:02:29",41,"( не не",151968,null],[153748,"2026-08-11T19:02:35",38,"— Спасибо...\n Лени берет все это и решил еще раз посмотреть на присутствие свободных столиков.",153743,null],[153749,"2026-08-11T19:03:14",47,"Дёшево",153718,null],[153760,"2026-08-11T19:05:10",55,".",153715,null],[153765,"2026-08-11T19:07:23",47,"Не обращая внимания на Эладрина Кейтлин продолжает играть мелодию из песни \"А мы не ангелы парень\". Лишь когда она заканчивает саму мелодию, она обращает на парня внимание:\n- Ты парень, вовсе не ангел - делает она умозаключение - но ладно, всякое бывает. Ты для чего в город приплыл то хоть?",151968,null],[153766,"2026-08-11T19:07:31",47,"/давайте вот так, повежливее",151968,null],[153768,"2026-08-11T19:09:54",55,"– Просто путешествую. Ищу для себя место в мире, если уж в широком смысле. \nОтвечает рыжеволосый машинально накручивая один из своих дредов на палец. \n– Сбежал из родной деревни, хочу мир повидать.",153765,null],[153769,"2026-08-11T19:10:42",47,"/ебать, а можно его увидеть, чтобы понимать с кем общается Кейтлин?",151968,null],[153770,"2026-08-11T19:10:56",55,"/ щас",153769,null],[153771,"2026-08-11T19:11:08",47,"Тип это Кейтлин",151968,null],[153772,"2026-08-11T19:11:28",47,"Её образ на выход +-",151968,null],[153774,"2026-08-11T19:11:59",55,"/ вот такое примерно",151968,null],[153775,"2026-08-11T19:12:14",47,"Понял. /",151968,null],[153778,"2026-08-11T19:13:53",9,"//Вы часом не на модный показ коллекции 409-го года от второго сотворения мира?)",151968,null],[153779,"2026-08-11T19:14:20",47,"/она сейчас в 1 образе. К сожалению нет",151968,null],[153781,"2026-08-11T19:15:26",38,"// Я думал на звание мисс вселенная для 409-го года",153778,null],[153784,"2026-08-11T19:15:52",47,"Ой, засмущали) /",151968,null],[153785,"2026-08-11T19:15:55",55,"/ можно тебя в ЛС похитить?)",153779,null],[153786,"2026-08-11T19:15:58",47,"/ну хватит мальчики)",151968,null],[153787,"2026-08-11T19:15:58",31,"Ну не всем же за уродов играть ит ли за крестьян сиводапых/",151968,null],[153788,"2026-08-11T19:16:04",47,"/го",153785,null],[153789,"2026-08-11T19:16:13",47,"У меня есть такой. /",153787,null],[153790,"2026-08-11T19:16:30",31,"У меня все такие. Ну может кроме Себастьяна/",153789,null],[153791,"2026-08-11T19:16:45",38,"// Хз парень вообще мой облик повторяет и со мной в 1 год разница.",153787,null],[153795,"2026-08-11T19:17:28",41,"Элиза была немного расстроена, что Кейт прекратила петь, но с другой стороны она уже наслушалась её пения в каюте",153765,null],[153796,"2026-08-11T19:17:39",31,"Их не появилось, более того за окном ты видишь очередь из потенциальных клиентов",153748,null],[153797,"2026-08-11T19:17:45",47,"/в каюте она наверное больше рисовала...",153795,null],[153798,"2026-08-11T19:17:59",47,"/она рисует, шьёт, поет, создаёт образы и взламывает замки",151968,null],[153800,"2026-08-11T19:18:46",38,"— Ох...\n Леви вздохнул и приняв судьбу сесть за стол с 3 незнакомцами, но и теперь будущими знакомыми пошел к столику и сказал.\n— Еще раз всем здравствуйте, могу ли я присесть?",153796,null],[153802,"2026-08-11T19:19:41",41,"Могильщица изподлобья взглянула на Леви",151968,null],[153812,"2026-08-11T19:22:18",38,"— Так можно или нет?\n Лени держал с собой еду и два кувшина с каким-то напитком.",151968,null],[153818,"2026-08-11T19:24:13",41,"— Кейт, можно? Мне все равно",151968,null],[153821,"2026-08-11T19:24:47",47,"Кейтлин отвечает:\n- Дамы любят когда мужчины за ними ухаживают. От этого мы становимся ухоженными - и подмигнула с намёком",151968,null],[153823,"2026-08-11T19:26:10",55,"– Можно конечно. Хотя мой голос уже ничего не решает. Хехе. \nЭльф улыбнулся Лени.",151968,null],[153825,"2026-08-11T19:27:06",41,"— и вы здесь... Кем будете?",151968,null],[153829,"2026-08-11T19:28:15",38,"Лени опустил еду и кувшины на стол и присел рядом.\n— Мисс, не думаю, что ваши намеки мне что-либо говорят...\n После этого Лени начал есть еду и пить напиток с кофе.\n— И почему только этот столик был свободен?...",151968,null],[153835,"2026-08-11T19:33:53",31,"Народ, я уже сейчас спать пойду, сейчас подкину вам пинок в сюжет, и можете социалить пока не дойдёте доечта, если пойдёте конечно, в утром продолжим//",151968,null],[153836,"2026-08-11T19:33:57",47,"- А я не намекаю, я прямо говорю, если за девушкой ухаживают, дарят ей хорошие вещи, то она радует весь мир вокруг своей красотой - хитрит Кейт",153829,null],[153838,"2026-08-11T19:34:40",41,"( споки",153835,null],[153839,"2026-08-11T19:35:41",41,"Элиза попивает кофе, не мешая Кейт развлекаться. Однако больше её внимания раправлено на Лени, самый Тихий на вид Именно он",153836,null],[153841,"2026-08-11T19:36:55",38,"— Я не ухажер или кто-то такой, поэтому скажу, что на меня можете не рассчитывать, потому что я не собираюсь влюбляться хотя бы до совершеннолетия.\n Лени продолжил есть мясо с хлебом и заметив, что его кофе начали пить он сказал.\n— Ох... Я то думал, куда делось кофе...\n Парень же пил из своего кувшина.",153836,null],[153842,"2026-08-11T19:38:11",47,"- Господи, какая молодёжь глупая пошла - недовольно вздохнула Кейт. И приступила к лёгкому перекусу.",151968,null],[153844,"2026-08-11T19:40:07",55,"– Дорогие друзья, давайте жить дружно! \nСказал Вейн и создал красивый сноп искр, напоминавший маленькие фейерверки.",151968,null],[153845,"2026-08-11T19:40:08",31,"В таверну пробирается мальчишка, которого очаровала Кейтлин, он находить ее глазами и подбегает к ней:\n\n- госпожа, мы кое что узнали, тот человек, что вы ищети, господин Шалье, портной из ремесленного района, сейчас в тюрьме. Мне велели передать, что если он вам нужен, то вас ждут по адресу Плацца-Валериана, 224, дом сиора Неро Феллино, он вроде как частный детектив и представляет интересы господина Шалье. И ещё... Ваших спутников там тоже ждут, вроде как сиор Феллино заинтересован во встрече со всеми вами и готов предложить какую то работу",151968,null],[153847,"2026-08-11T19:40:58",31,"- вот карточка с местом расположения дома сиора Феллино",151968,null],[153848,"2026-08-11T19:41:35",31,"- это недалеко, если решите пойти, я провожу\n\n*с обожанием смотрит на Кейтлин*",151968,null],[153850,"2026-08-11T19:42:06",55,"/ дожили бард детей очаровывает...",151968,null],[153851,"2026-08-11T19:42:14",38,"Лени немного дернулся и чуть не подавился своим же кофе.\n— Кха-кха! А нас то зачем?... Уааа...\n Парень еще раз отдышался и сказал дальше.\n— Мы то где?",151968,null],[153852,"2026-08-11T19:42:35",31,"Случайная жертва обаяния))//",153850,null],[153853,"2026-08-11T19:44:08",31,"- сиор Феллино всегда интересуется новыми людьми в городе. Он выслушал описание и решил что вы ему интересны. Я не знаю подробностей, что там у него в голове, но он платит за информацию и мы ее предоставляем. Он хороший, сиор Феллино, просто странный чуток, из дома почти не выходит",153851,null],[153854,"2026-08-11T19:45:27",38,"// На сколько лет ребенок?",153853,null],[153855,"2026-08-11T19:45:43",31,"13-14/",153854,null],[153856,"2026-08-11T19:47:39",31,"Все, я спать пойду, уже полночь почти у меня. Завтра почитаю что вы тут напишите, если напишите//",151968,null],[153858,"2026-08-11T19:48:21",38,"— Тебе бы книжки почитать или пойти в подмастерье, хотя... бегай дальше, не повторяй мою судьбу...\n Лени вздохнул и сказал уже \"знакомым\".\n— Кстати забыл представится, Лени.",153853,null],[153862,"2026-08-11T19:49:25",41,"— Спасибо, мальчик \n\nОна дает ему золотой",153845,null],[153863,"2026-08-11T19:50:09",41,"— Мы Элиза \n\nОна укаэет на себя\n\nИ Кейтлин \n\nУкажет на Кейт",151968,null],[153880,"2026-08-11T19:54:03",38,"// Можешь подробно описать себя, точнее Элизу",153863,null],[153899,"2026-08-11T20:00:00",47,"Кейтлин спускается ниже и гладит мальчонку по голове:\n- Тебе за помощь спасибо. Вот тебе 10 монеток (серебро ссыпала). Умничка - ещё и в щечку поцеловала - был бы взрослый, я бы замуж вышла - ещё немного поворошила волосы, тяжело вздохнула и обратилась к остальным:\n- Нам необходимо помочь этому человеку. Он слишком великолепен, чтобы находиться в тюрьме. Я думаю он вас наградит. \n Я думаю вас приняли за сопровождающих, потому и тоже приглашают в гости. Я рекомендую вам не выежиыаться, связи это полезные",151968,null],[153901,"2026-08-11T20:01:40",41,"( можно мне немного времени? Уборка(",153880,null],[153907,"2026-08-11T20:02:49",38,"Лени посмотрел на пацана и помотав головой открыл книгу и записал пером с остаткам чернил, на Великаньем.\n\"Никогда не приближаться к девушкам и женщинам младше и старше себя. Особенно не трогать дам в возрасте...\"\n— Если вы так сильно хотите меня привлечь, то постарайтесь получше, просто у меня другие интересы.",153899,null],[153924,"2026-08-11T20:11:19",47,"- Мне всё равно, это ты к нам подсел - уже равнодушно повела плечом Кейт",151968,null],[153933,"2026-08-11T20:14:33",55,"– Так , чоотза драмы вы тут устроили? Я за то , чтобы помочь детективу. Раз уж на то пошло.",151968,null],[153959,"2026-08-11T20:25:42",47,"- Вот это слова настоящего мужчины - отметила Кейтлин улыбнувшись",151968,null],[154101,"2026-08-12T03:34:38",31,"Перекусив, вы отправились по указанному адресу и нарисованному плану. За тот час, что вы провели в таверне, погода испортилась, набежали тучи, дождь заморосил, а резкие порывы ветра регулярно заставляли дождевые капли менять направление и нападать на вас с разных сторон. Благо, идти оказалось недалеко, и миновав все пару переулков, вы оказались на границе статорого города, купеческого и портового районов. Тут то и прятался небольшой двухэтажный домик, которые от любоптынз глаз закрывали растушие в небольшом садике деревья",151968,null],[154102,"2026-08-12T06:35:37",31,"//народ, если что, я готов принимать заявки даже если не все тут находятся, думаю, собирать всех в одно время и играть строго всем сразу это утопия, так что одиночный либо там парный отыгрыши имеют право на жизнь. Те кто пока не присутствуют, могут потом включится. Также не стесняйтесь бросать кубы на проверки чего либо, главное объясняйте, для чего вам это, им что ищете или желаете проверить. Нет смысла бросать например запугивание просто так, я это интерпретирую как вой на луну//",151968,null],[154120,"2026-08-12T08:28:30",38,"Лени ещё при выходе из таверны снова сменил наряд одежды на свой 4 вариант.\n Пройдя поближе к месту назначения Лени сказал.\n— Довольно красивый дом... Вот только не создан он для дождевых погод...",151968,null],[154131,"2026-08-12T08:51:32",41,"( погодите, скоро буду",151968,null],[154595,"2026-08-12T12:42:52",41,"Элиза шла рядом с Кейтлин, прекрывая её от дождя своим плащом. \n\nПодходя к домику она достаточно громко постучит в дверь. \n\n— Мы пришли помочь детективу!",151968,null],[154598,"2026-08-12T12:44:06",31,"Откуда то со второго этажа вы слышите зычный голос:\n\n_- не заперто, поднимайтесь",154595,null],[154646,"2026-08-12T12:58:58",31,"Отозвавшись на голос, вы поднимаетесь в богато обставленный кабинет, где за столом в роскошном красном кожаном кресле сидит огромный пожилой табакси. Он покуривает трубку и с интересом рассматривает вас через полузакрытые глаза",151968,null],[154648,"2026-08-12T12:59:16",47,"Ебать",151968,null],[154649,"2026-08-12T12:59:25",47,"Кейтлин тихо хихикнула",151968,null],[154652,"2026-08-12T13:01:08",41,"— Добрый вечер. Мы пришли услышать подробности нашего расследования",151968,null],[154653,"2026-08-12T13:01:18",31,"- весьма рад, что вы нашли время навестить меня, не испугавшись столь отвратительнрой погоды\n\n*в словах табакси явно слышится неприязьнь к местном климату\"",151968,null],[154655,"2026-08-12T13:01:57",31,"- вашего? я думал сам предложить вам работу, а вы оказывается уже и сами что то расследуете? любопытно..",154652,null],[154656,"2026-08-12T13:02:04",41,"( бляяя",151968,null],[154658,"2026-08-12T13:02:17",41,"( не, Эле надо спать",151968,null],[154659,"2026-08-12T13:02:46",31,"отдохни лучше, не мучь себя//",154658,null],[154660,"2026-08-12T13:03:11",41,"( ага",151968,null],[154666,"2026-08-12T13:04:39",31,"ну в принципе можем с остальными участникаи поболтать, все равно кроме Миши пока никого и нет. бкдем играть в режиме сломанного телефона, кто то зашел в телегу, закинул что то, я буду отвечать. может к вечеру что то и обсудим//",151968,null],[154675,"2026-08-12T13:07:02",47,"- Конечно, ведь мы прекрасно понимаем, что чем быстрее выполним задачу, тем быстрее достигнем общих целей, а это позволит нам получить некие преимущества -  забалтывает Кейтлин",151968,null],[154695,"2026-08-12T13:18:00",31,"Неро Феллино складывает пухлые ручки на пузе, разговор его забавляет:\n\n- хорошо говорите, сиора. вроде много и по существу, а ничего по факту не сказали и не пообещали. Не думали о карьере в политике или юриспруденции? Ну да ладно, я знаю зачем лично вы пришли. Шалье, верно? Он в тюрьме, стандартаня история для нашего города торговцев, не поделился с кем нужно. Я его конечно вытащу и вы сможете увидится после его осовбождения. Но на это уйдет несколько дней, может неделя, мои сотрудники уже занимаются этим. А во что касется вашей пестрой компании, то ваше описание от портовых мальчишек меня заинтересовало: девушка с лопатой могильщика, красотка-бард, редкий даже для нашего города эльф со способностями к магии и юноша что все записывает. я, знаете ли, в силу своей природы, весьма любопытен и люблю неоычных людей. А тут еще и новое дело наклюнулось, одна старушка пишет что пропал ее оракул. Ну конечно я не могу упустить шанс взять дело с магическим душком и не позвать себе на помошь компанию, члены которой очевидно тоже что то смыслят в магии",151968,null],[154783,"2026-08-12T14:19:44",47,"- Что же. Жаль, что наши усилия и результаты по расследованию окажутся не нужными, но уже налаженные связи и потоки информации будут полезны и в этом деле, господин - опять ничего чёткого, но очень красиво говорит (могу убеждение кинуть коли надо) - у меня тоже случилась потеря. Одна не очень красивая девушка украла у меня возможность попасть к господину Шалье, и я бы очень хотела в свою очередь вернуть эту возможность - обозначила свои пожелания девушка, буквально в воздух, не говоря прямо, но намёком жирным ставя свою хотелку на обозрение",151968,null],[154798,"2026-08-12T14:23:32",38,"— Сэр...\n Сказал парень и выйдя вперёд сказал.\n— Я думаю меня хотя бы не надо брать на такое задание, ну какой из меня сыщик или детектив, я просто недавно вышел в свет из своего прошлого места работы, да и только!",154695,null],[154828,"2026-08-12T14:29:46",47,"/может быть очарование личности наложить и нехай бесплатно работает?",151968,null],[154945,"2026-08-12T14:44:36",31,"- насколько я понял, вы, молодой человек, стремитесь к карьере писателя? А как же вы будете описывать человеческие взаимоотношения, прозу жизни, да банально прямую речь представителей разных слоев населения, если не увидите это вблизи? Будете придумывать? Ну тогда потом не удивляйтесь, если вашим рассказам не будут верить. Я вас не неволю и наьотать на себя не заставляю, даже готов платить за это. Не хотите - чтоже, дверь за вашей спиной. Или еще подумаете?",154798,null],[154957,"2026-08-12T14:45:52",31,"- о, человеческие страсти, похищения, я это люблю, я с этого, простите за нескромность, живу. Расскажите пооодробнее? Все равно мне нужно убить время до прихода клиентки",154783,null],[154974,"2026-08-12T14:49:09",31,"Бля, вот как чувствовал, что будет кто то квестодателя обижать, даже статблок для него сделал)) но надеюсь до конфронтации не дойдет//",154828,null],[154989,"2026-08-12T14:51:02",47,"- Вергилия, моя дорогая подруга, что жила со мной в Веспирали украла моё приглашение к господину Шалье, где была возможность обратиться \n к экспертам красоты и моды, получить от них несколько уроков и выступить на конкурсе Мисс Города - Кейтлин слегка пиздела, но сложновато понять, она слишком хороша в этом",151968,null],[154991,"2026-08-12T14:51:11",47,"/против квестопринимателя",154974,null],[155013,"2026-08-12T14:52:46",31,"- хохо, ну думаю если вы таки мне поможете, то уж перед господином Шалья я словечко замолвлю",154989,null],[155020,"2026-08-12T14:53:10",38,"Лени хотел что-то сказать но умолк и немного обдумав сказал.\n— Откуда вы вообще знаете, кем я хочу стать? Я же сказал это буквально один раз и то недавно...",151968,null],[155044,"2026-08-12T14:54:53",31,"- моя работа знать всё. Вы думаете что на меня работают только мальчишки на портовой площади? Я сам стеснен в передвижениях, но ушей у меня много. Хотя в вашем случае да, мне скорее повезло, мой агент был с вами в одной портовой конторе, возвращался с заказа в другом городе",155020,null],[155362,"2026-08-12T15:40:42",38,"— Понятно... Еще раз, сколько вы заплатите за это задание?\n Спросил Лени и немного виновато почесал затылок.",155044,null],[155411,"2026-08-12T15:53:42",31,"Сиор Неро откинулся на спинку кресла и довольно сощурил глаза\n\n- 100 золотых на группу. Ну и если найдете какую нибудь халтурку, на нее не претендую, главное чтобы не в ущерб основному расследованию.",155362,null],[155412,"2026-08-12T15:54:55",31,"- и да, главное что можно заработать в этом городе - это связи. Это торговый город, тут ценят тех кто умеет торговаться и придерживается принципа ты мне - я тебе",151968,null],[155420,"2026-08-12T15:55:57",38,"— Хм... Я согласен с этим...\n Сказал Лени задумавшись и продолжил.\n— То есть нам нужно решить проблему с оракулом у одной бабушки?",155411,null],[155446,"2026-08-12T15:58:35",31,"Сиор Неро сменил ОЗУ, появилась какая то неловкость:\n\n- честно признаться, я сам пока не совсем в курсе, мне лишь пришло письмо, где пожилая сиора просила помощи в поиске ее оракула. А я, при всей своей осведомлённости никогда не слышал о каких то личных оракулах. Так что жду потенциальную клиентку с немалым интересом. Люблю загадки, знаете ли",155420,null],[155454,"2026-08-12T15:59:38",55,"/ ох ёлки",151968,null],[155459,"2026-08-12T16:00:19",38,"— И когда сиора придет сюда?",155446,null],[155461,"2026-08-12T16:00:47",31,"Смотрит на часы:\n\n- совсем скоро, не более 20 минут",155459,null],[155468,"2026-08-12T16:03:14",38,"— Тогда...\n Лени осмотрелся в поисках куда бы присесть.\n— Я могу присесть на это время?",155461,null],[155472,"2026-08-12T16:04:20",55,"/ так как мне подключиться-то теперь думаю. Отдельно после всех приплестись?",151968,null],[155474,"2026-08-12T16:04:49",31,"*ленивый взмах лапой в сторону нескольких желтых кресел, что стоят с вашей стороны стола*",155468,null],[155475,"2026-08-12T16:05:04",31,"Просто подключайся и все, ты со всех ми в кабинете/",155472,null],[155477,"2026-08-12T16:05:36",55,"/ щас только дочитаю диалоги",155475,null],[155478,"2026-08-12T16:05:43",38,"Лени немного кланяется и садится на одну и... Они удобные.\n\"Довольно удобные...\"\n Парень продолжил сидеть на кресле.",155474,null],[155502,"2026-08-12T16:12:20",55,"Эльф это время просто молчал, иногда фыркая на словоблудство Кейтлин. Когда же присесть предложили , то он присел на одно из кресел. \n\n– Тогда стоит подождать сиору и узнать, что вообще представляет из себя её оракул.",151968,null],[155510,"2026-08-12T16:13:32",31,"Минут через 30-40 реального времени отпишу, сейчас чуток занят//",151968,null],[155667,"2026-08-12T16:47:35",31,"По истечение примерно 10 минут раздался неуверенный стук в дверь. Хозяин дома что то сказал на неизвестном вам языке (возможно, это был язык табакси, для вас прозвучало как мяу), и материализовавшийся в офисе слуга-табакси побежал вниз встречать гостью. Пожилая дама со скромным лицом несколько удивилась числу присутствующих, но очевидно ее воспитание не позволило ей слишком уж сильно выражать свои чувства на людях.\n\nНеро:\n\n- здравствуйте, сиора ди Бьяко, я получил ваше письмо и заинтересован вашим делом. Эти молодые люди - оперативники, они и займутся вашим делом на улицах, при них вы можете все рассказать. Давайте даже так, они и проведут опрос, ну а я помогу в случае необходимости\n\nСтарушка смотрит на вас с некоторой неуверенностью, го очевидно что авторитет старого детектива перевешивает:\n\n- что же, если вы думаете что это лучшее решение, то я не буду спорить. Спрашивайте",151968,null],[155712,"2026-08-12T16:58:21",38,"Лени достал записную книжку и перо с чернилами начав писать.\n— Как зовут оракула? Как вы узнали что он пропал? Когда? Кем он вам приходится? Где он обычно бывает? Говорил ли он вам что-то перед уходом?",151968,null],[155728,"2026-08-12T17:01:46",47,"Кейтлин, пока Лени допрашивал женщину подошла к слуге и попросила устроить возможность для небольшого чаепития, когда Лени закончил допрос, она осторожно коснулась женщины и сказала:\n- Скажите, дело требует спешки? Если нет, то предлагаю в спокойной обстановке выпить чаю и обсудить дело - уверенны действия, милая улыбка. Ощущение будто здесь Кейтлин хозяйка дома (охеревшая мадам, да)",151968,null],[155742,"2026-08-12T17:07:56",31,"-Пьетро, моего малыша зовут Пьетро (утирает слезы). Утром я не нашла его на его насесте, только пёрышки остались. Он ничего не говорил, он же петух. Он очень умный, он всегда предупреждал меня о том что этот старый козел Беппо Кольби опять строит мне кознииии\n\nСтарушка заливается слезами",155712,null],[155746,"2026-08-12T17:09:17",31,"- сиор Неро не любит когда клинтов отвлекают",155728,null],[155818,"2026-08-12T17:21:23",55,"– Оракул... Петух?\nВейн сначала казалось впал в ступор. \n– То есть каким-то образом петух давал понять, что я так понимаю ваш сосед устраивает вам неприятности? Нда... Я ничего не знаю об этом мире. Теперь я точно в этом убедился. \nОн встал всплеснул руками. \n– То есть, дорогие мои товарищи поневоле, мы должны найти петуха , который возможно уже пущен на суп? Ну просто если то, что уважаемая сиора говорит – это правда. То со стороны сиора Кольби было бы логично просто выкрасть и съесть надоедливую помеху. То есть максимум , что мы сможем обнаружить – это его кости. Уж простите , сиора, но это самый вероятный вывод из вашей истории.",151968,null],[155822,"2026-08-12T17:21:34",38,"— То есть вашим оракулом был Петух по имени Пьетро? Как именно он вас предупреждал и почему он оракул?",155742,null],[155846,"2026-08-12T17:23:11",31,"Даже если это так, я должна знать правду! И призвать негодяя к ответственности! Я уверена, тот, у кого поднялась рука на невинную птицу не может быть хорошим честным человеком!",155818,null],[155853,"2026-08-12T17:23:46",41,"( кажется я много пропустила, скоро присоединюсь",151968,null],[155858,"2026-08-12T17:24:30",31,"- он, Пьетро, всегда громко кричал если мой сосед, зловредный Беппо, оказался поблизости. А я знаю этого старого козла с юности, он всегда меня ненавидел и строил козни. И только малыш Пьетро всегда меня предупреждал",155822,null],[155942,"2026-08-12T17:40:59",55,"– Ладно, допустим, дорогие мои друзья, какие будут предложения? Самое очевидное – это допросить самого Беппо. Ну и , возможно, отбить при этом у него желание вредить несчастной старушке. Но может  разделиться и кто-тоосмотрить курятник где жил Пьетро? Мне очевидно проще прижучить старикашку, нежели выискивать следы. \nВыдвинул своё предложение эльф и сел на место.",151968,null],[155959,"2026-08-12T17:43:14",38,"— Помнишь, что произошло на пропускном пункте? Я тебя в тот раз отмазал, потому что знал, что ты его не тронул, а вот теперь я тебя точно не спасу...\n Ответил Лени и записал все к себе.\n— Так... сиора ди Бьяко, тогда вам можно завести другого питомца, к примеру кота или собаку или снова петуха, что будет выполнять ваше же задание, но а пока что мы поищем вашего Пьетро..",155942,null],[156059,"2026-08-12T17:56:48",31,"- мне нужна правда о судьбе Пьетро. И наказание для того, кто обидел моего малыша!\n\nСтарушка очевидно успокоилась и закопалась в броню хорошего воспитания!\n\n- Сиор Феллини, если ко мне больше нет вопросов, я бы хотела вернуться домой. Вы или ваши сотрудники можете найти меня там в случае необходимости.\n\nСтарушка удаляется, а детектив-таьакси переводит взгляд на вас. Видимо, сейчас будет какой то разбор.",155959,null],[156098,"2026-08-12T18:03:27",31,"Сиор Феллино смотрит на вас молча примерно минуту. \n\n- чтоже, я не ждал такого. Я не занимался поиском домашних питомцев лет так 40, с тех времен когда только начинал практику. И сейчас корю себя за наивность, услушальпро оракула и воспринял это всерьез. Но ка бы то ни было, дело принято, награда обещана, а аванс выплачен. Желаю вам удачи в вашем поиске... Петуха. Или кго убийцы, спаси Аскелатор его душу. И наверное да, лучше всего начать с разговора с сиором Беппо, которого хозяйка петуха подозревает в первую очередь. Должен признаться, во всей этой истории меня смущает только момент с тем, что петух реагировал на приближение этого человека. Я сомневаюсь в наличие у птицы таких способностей, думаю тут есть что копать. В любом случае, даже если петух мёртв, нужно найти его останки или другие доказательства, как бы смешно это не звучало. Правда, как за это всерьез привлечь похитителя к ответственности я пока не знаю. Но придумаю.",151968,null],[156099,"2026-08-12T18:04:19",31,"/если есть что сказать - говорите/",151968,null],[156103,"2026-08-12T18:05:17",41,"( Погодите, могу прочитать минут за 10",151968,null],[156104,"2026-08-12T18:05:19",41,"?",151968,null],[156115,"2026-08-12T18:06:11",38,"— Думаю у Петуха механизм с восхода солнца был заменен на приближение мужчины или просто привычка, как домашнего животного.",156098,null],[156120,"2026-08-12T18:06:45",31,"Читай/",156103,null],[156149,"2026-08-12T18:09:41",31,"- то есть ты думаешь, что он как то надрессировал петуха соседки? А уж как поменять механизм восхода солнца, я и вовсе не представляю.",156115,null],[156151,"2026-08-12T18:10:38",38,"*// Она*",156149,null],[156153,"2026-08-12T18:11:07",38,"// Блять я тупой",151968,null],[156180,"2026-08-12T18:16:07",41,"— в здешних краях многие животные при хозяйстве ассоциируются с магией и прорицанием. Ничего удивительного в этом нет \n\nЗаключила девушка, поправляя свои перчатки для работы",156115,null],[156189,"2026-08-12T18:17:47",31,"Неро Феллино:\n\n- ладно, думаю, вам уже пора. Если будут вопросы, я всегда тут и постараюсь помочь советом или знакомством",151968,null],[156198,"2026-08-12T18:19:20",38,"Лени немного удивился от этого и вскинул руки.\n— Еще лучше... И ты хочешь сказать, что здесь каждый знает школу прорицания?\n Парень немного вздохнул и взяв свои вещи изменил свою одежду на довольно опрятная одежду с мантией поверх.\n— Тогда... сэр, мы пойдем на это дело...",151968,null],[156203,"2026-08-12T18:20:05",55,"/ сорри у меня с интернетом перебои",151968,null],[156234,"2026-08-12T18:24:26",31,"//надеюсь, я смог вас удивить началом?)))//",151968,null],[156235,"2026-08-12T18:24:36",38,"// Петух...",156234,null],[156237,"2026-08-12T18:24:58",55,"/ скорее мы кринжа словили. Петух ... Это не в упрёк если что",156234,null],[156238,"2026-08-12T18:25:22",31,"//хехе, ну не всегда же мир спасать в квесте)))//",151968,null],[156239,"2026-08-12T18:26:58",55,"– Сиор, может подскажите как нам найти дом этого Беппо?\nСпросил эльф, остановившись. \n– И никто ж даже не догадался спросить где он живёт. \nОн посмотрел на своих нынешних товарищей с упрёком.",156189,null],[156240,"2026-08-12T18:27:20",55,"/ Да ну понятно. Но... Петух?",156238,null],[156242,"2026-08-12T18:27:40",31,"//ну просто петух, а оракул)))//",156240,null],[156243,"2026-08-12T18:27:56",38,"— Я хотел пойти догнать мисс, чтобы узнать это.",156239,null],[156244,"2026-08-12T18:28:25",31,"- не нужно, у нас есть ее письмо с обратным адресом",156243,null],[156245,"2026-08-12T18:28:44",41,"( Мне нравится",156234,null],[156247,"2026-08-12T18:29:14",41,"— Мне кажется, расследование стоит начать с места преступления",156239,null],[156248,"2026-08-12T18:29:25",31,"- виа пальми, 17, это в Старом городе. Полагаю, соедк должен жить рядом",151968,null],[156251,"2026-08-12T18:31:09",31,"Честно тебе скажу, это мой недописанный рассказ. Он родился тупо из двух слов, петух и оракул. Я его так и не дописал, хотя вся структура готова. Ну хоть проверю на вас, насколько она логична//",156240,null],[156253,"2026-08-12T18:31:50",41,"( круто же",156251,null],[156271,"2026-08-12T18:35:42",55,"– Ну я уже об этом говорил и предложил разделиться. Кто-то на место преступления. Я пойду к соседу. Не силён я во всяких загадках. \n\nОтветил Вейн и вышел из офиса детектива.",156247,null],[156285,"2026-08-12T18:38:51",41,"— Раздельно кажется быстрее, Но в общей группе Мы будем лучше дополнять друг друга. Отец с матерью так всю жизнь проработали, а нас четверо",156271,null],[156300,"2026-08-12T18:41:30",55,"– Ну вроде бы и да... Но мы даже толком и не знаем друг друга. Надо всё же познакомиться будет.",156285,null],[156308,"2026-08-12T18:42:02",55,"/ предположим, что все уже вышли",151968,null],[156309,"2026-08-12T18:42:34",38,"— Тогда я к соседу, к мисс ,чтобы проверить сведения, а вы можете все втроем пойти к соседу.\n Лени накинул капюшон на себя и поклонившись направился к мисс",151968,null],[156318,"2026-08-12T18:44:06",41,"— Это ближе к решению. У чужого дома много людей подозрительно. А вот у курятнике вполне...",156309,null],[156338,"2026-08-12T18:46:39",31,"Короче, определяйтесь как разделились и кто куда пойдет и я вас отведу//",151968,null],[156339,"2026-08-12T18:46:50",47,"Кейт к соседу. Пиздеть она умеет",151968,null],[156341,"2026-08-12T18:47:08",31,"В любом случае вы можете идти все толпой и разделится уже на месте/",151968,null],[156352,"2026-08-12T18:50:46",55,"/ Вейн с ней. Ну оба пиздеть умеют. Напугают до усрачки😂",156339,null],[156359,"2026-08-12T18:51:42",47,"/она больше убеждать и обманывать...",151968,null],[156360,"2026-08-12T18:51:51",47,"/меньше 17 выкинуть физически не могу",151968,null],[156361,"2026-08-12T18:52:04",31,"Можете договорится о тактике ведения допроса/",156359,null],[156362,"2026-08-12T18:52:05",41,"( ок я одна к курятнику",151968,null],[156363,"2026-08-12T18:52:21",31,"С тобой вроде Лени/",156362,null],[156364,"2026-08-12T18:52:32",38,"// Ты со мной идешь, я тоже к мисс",156362,null],[156365,"2026-08-12T18:52:35",41,"( Тогда попуиаоась",151968,null],[156366,"2026-08-12T18:52:43",47,"- Давай я начну и если он совсем будет выёбываться приступишь ты к допросу? - предлагает она тактику",151968,null],[156367,"2026-08-12T18:54:03",41,"— будьте осторожны. Стража может сбежаться на любой повод",151968,null],[156368,"2026-08-12T18:54:53",55,"– Ну хорошо. Посмотрим, что получится у тебя. Игра \"плохой-хороший стражник.\"\nСогласился эльф.",156366,null],[156372,"2026-08-12T18:56:15",31,"Выйдя из дома детектива вы вновь увидели изменение погоды. Теперь солнце светит ярко, туч нет, как и малейших признаков ветра. А прошло то всего чуть больше часа.\n\nДом сиоры Лукреции ди Бьякко, вашей клиентки, находится в Старом городе, совсем неподалёку от дома-когторы детектива, вы дозодите туда буквально за 15 минут неспешного шага. \n\nДомик сиоры ди Бьякко ал размеру превосходит жлье детектива, аккуратный садик перед ним явно составляет предмет гордости хозяйка. Еюв его глубине вы видите просторный вольер, возможно именно там и жил петух",151968,null],[156376,"2026-08-12T18:56:50",31,"Где находится дом соседа Беппо вы не знаете, но по логике, он где то рядом, как бы его найти?",151968,null],[156378,"2026-08-12T18:58:18",38,"— Так... Ребят вы спросите у местных где дом этого соседа, а мы разберемся с этим Пьетро...",151968,null],[156382,"2026-08-12T18:59:07",55,"/ Они ж даже по имени не знают друг друга, да?...",151968,null],[156385,"2026-08-12T18:59:50",38,"// Ну вы представлялись и мой персонаж тоже",156382,null],[156411,"2026-08-12T19:04:02",41,"Прийдя к домику Элиза осмотрится. Получила ли она ключ от калитки? Может где-то лежит запасной?",151968,null],[156414,"2026-08-12T19:04:26",41,"/r d20+2 внисательность пассивная пятнадцать",151968,null],[156416,"2026-08-12T19:04:28",55,"– Договорились. \nОн повернулся к музыкантке\n– Кейтлин, пойдём? Лени, мне кажется, смышлёный парень, а Элиза в обиду его не даст в случае чего.",156378,null],[156421,"2026-08-12T19:05:00",31,"Объясни мне пожалуйста, что это значит?/",156415,null],[156424,"2026-08-12T19:05:22",31,"Мне учитывать 15 или 4?/",151968,null],[156433,"2026-08-12T19:05:53",38,"// Если бросок не сработал, то персонаж пассивно имеет 15. Вообще мастер сам решает какой использовать",156424,null],[156440,"2026-08-12T19:07:02",38,"// К примеру у меня это 12",151968,null],[156443,"2026-08-12T19:07:12",31,"Ну ок. Ниразу так не играл, у меня если выпадало 5 на внимательностью, это всегда было 5, без вариантов))",151968,null],[156447,"2026-08-12T19:07:59",31,"Ты не обнаруживаешь тут ключа. Да тут и замка то нет, клетка закрывается на деревянную вертушку",156414,null],[156451,"2026-08-12T19:09:26",41,"( калитка?",151968,null],[156455,"2026-08-12T19:10:24",31,"Точно, я ошибся, думал ты про вольер птичий. Ну калитка тоже не заперта, хозяйка дома",156451,null],[156461,"2026-08-12T19:11:36",38,"Лени проходит за калитку и говорит немного громко.\n— Это детективы, простите за вторжение!\n После этого Лени осмотрелся на внешний вид двора.",151968,null],[156466,"2026-08-12T19:13:07",31,"Клиентка выглянула из окна, узнала вас и вышла в сад. \n\n- а зачем вы ко мне? Я думала вы сразу к Беппо пойдёте и питжменкт старого негодяя к ногтю. Он вон там живет\n\nТыкает пальцем через дорогу под углом",156461,null],[156471,"2026-08-12T19:14:39",38,"— Как раз еще была неполадка в этом... Элиза можете сказать им, где дом?\n Затем Лени повернулся обратно и сказал.\n— Можно тогда мы осмотрим птичий вольер? Просто хочется узнать что такого необычного в Пьетро раз он помогал вам.",156466,null],[156479,"2026-08-12T19:15:32",55,"/ буду значит ждать Кейтлин... Ну то есть Мишу",151968,null],[156480,"2026-08-12T19:15:39",31,"- Пьетро был даром божьим, истинно говорю вам. А старый козел живёт воон там, в доме с мерзкими башенками",156471,null],[156488,"2026-08-12T19:18:57",31,"Примерно так выглядит дом беппо. Только вокруг другие дом есть, он вписан в улицу",151968,null],[156492,"2026-08-12T19:20:10",55,"/ Потом окажется что он колдун и принё петуха в жертву \"Папочке\" или \"Мамочке\"",156488,null],[156495,"2026-08-12T19:20:34",38,"// Исчадие, что говорит своему последователю делать пакости старушке",156492,null],[156502,"2026-08-12T19:22:22",47,"Кейтлин кивает",151968,null],[156503,"2026-08-12T19:22:24",47,"@FelixFadeev",151968,null],[156505,"2026-08-12T19:22:36",47,"/пока найди дом. Я маленько занят...",151968,null],[156524,"2026-08-12T19:27:58",55,"/ а там забор с калиткой есть или он просто так и стоит?",156488,null],[156527,"2026-08-12T19:28:26",31,"Есть забор, есть калитка",156524,null],[156529,"2026-08-12T19:28:31",41,"( Тогда калитку. Птичью клетку я не открываю",156455,null],[156534,"2026-08-12T19:29:07",31,"Там уже клиентка вышла, встретила вас/",156529,null],[156541,"2026-08-12T19:30:12",41,"( ааа блин, отвлекалась",151968,null],[156544,"2026-08-12T19:30:59",55,"Эльф подошёл к калитке  дома Беппо. \n– Хозяин, открывай! К вам есть пара вопросов!\nКрикнул он достаточно громко , чтобы даже самый старый и глухой дед услышал.",156488,null],[156545,"2026-08-12T19:31:02",41,"— обычно любой вор оставляет хоть один след. Мы пришли Это проверить. Лени, осмотри калитку. А я посмотрю землю вокруг",156466,null],[156566,"2026-08-12T19:34:44",31,"На втором этаже дома открывается окно, оттуда высовывается взлозмвченгая голова\n\n- вы кто такие? Я вас не звал! идите прочь, у меня эксперимент!\n\nГолова пропадает, окно закрывается",156544,null],[156569,"2026-08-12T19:35:08",38,"// Вы кто такие? Я вас не звал! ИДИТЕ НАХУЙ!",156566,null],[156571,"2026-08-12T19:35:09",47,"Кейтлин тяжко вздыхает и пытается пройти, если не получается, она готова взломать калитку",151968,null],[156577,"2026-08-12T19:35:27",31,"Классику знаешь, молодец/",156569,null],[156579,"2026-08-12T19:35:49",47,"/щас начнётся жесть...",151968,null],[156580,"2026-08-12T19:35:54",47,"Сори сразу/",151968,null],[156583,"2026-08-12T19:36:01",31,"Калитка заперта",156571,null],[156588,"2026-08-12T19:36:38",31,"На лютую жесть прибежит городская стража)/",156579,null],[156589,"2026-08-12T19:36:41",47,"Взламываю",156583,null],[156592,"2026-08-12T19:36:54",47,"Использование магии разума. Это лютая жесть, но невидимая",156588,null],[156594,"2026-08-12T19:37:05",47,"/r +d20+5 с помощью друга",151968,null],[156596,"2026-08-12T19:37:21",47,"Я так понимаю это вообще незаметно и тихо...",151968,null],[156597,"2026-08-12T19:37:29",31,"Расскажи как взломал. Тут понятно что успешно/",151968,null],[156598,"2026-08-12T19:38:38",47,"У меня есть набор взломщика. Я аккуратно достаю отмычки и пока эльф отвлёкся и вообще никто не смотрит два ловких движения пальцами... Замок видимо слишком простой был. Щелчок",151968,null],[156600,"2026-08-12T19:38:47",31,"На осмотр земли точно нужно будет кинуть внимание/",156545,null],[156603,"2026-08-12T19:39:09",31,"Вы проникли во двор дома Беппо",156598,null],[156606,"2026-08-12T19:39:37",31,"Двор захламлен всякими железяками, механизмами и прочим техническим мусором",151968,null],[156607,"2026-08-12T19:39:51",47,"- За мной и дай две минуты",151968,null],[156618,"2026-08-12T19:40:52",47,"Кейтлин тратит две минуты и за счёт набора для грима скрывает своё лицо и лицо эльфа, чтобы их если что не опознали. Одевает другое платье и снимает украшения по которым её можно опознать. Надевает парик. Тоже самое с эльфом. Только после они заходят в дом ебанутого",151968,null],[156620,"2026-08-12T19:41:09",47,"Эльф сопротивляется?",151968,null],[156626,"2026-08-12T19:41:35",41,"/r d20+2",156600,null],[156628,"2026-08-12T19:41:41",47,"@FelixFadeev",151968,null],[156633,"2026-08-12T19:41:53",41,"( я землю копаю каждый день!",151968,null],[156646,"2026-08-12T19:42:54",55,"/ секунду",151968,null],[156649,"2026-08-12T19:43:04",31,"Ты видишь что трава примята, даже можно сказать истоптана сапожищами, словно несчастного петуха долго не могли поймать и гонялись за ним по всему вольеру",156626,null],[156658,"2026-08-12T19:44:32",31,"Вы слышите что старик что то делает на втором этаже, бегает, ругается сам на себя, чем то гремит",156618,null],[156663,"2026-08-12T19:45:06",41,"— Прыткий... А что на счет криков...? \n\nОна поищет зацепки оружия. Могли ли петуху повредить клюв? \n\n( плот твист - она находит отрезанную голову)",151968,null],[156665,"2026-08-12T19:45:24",55,"– Э , куда... Ты чего? Хоть бы... Ай ладно. \nОн не сопротивляется и даёт возможность хитрой девушке замаскировать себя.",156620,null],[156677,"2026-08-12T19:46:25",47,"Поднимаемся наверх",151968,null],[156678,"2026-08-12T19:46:31",31,"Следов крови нет",156663,null],[156680,"2026-08-12T19:46:58",41,"( прикол с головой кто-то понял?",151968,null],[156681,"2026-08-12T19:47:11",55,"/А как наверх. Она же только калитку взломала, не?",156677,null],[156682,"2026-08-12T19:47:16",41,"( я чувствую только Лёша понял и не палится",151968,null],[156683,"2026-08-12T19:47:19",31,"На втором этаже вы видите что то вроде лабораторного стола, уставленного приборами, сам хозяин дома настраивает какой то механизм",156677,null],[156685,"2026-08-12T19:47:42",55,"/ ладно",151968,null],[156686,"2026-08-12T19:47:45",31,"Нет, увы//",156682,null],[156690,"2026-08-12T19:48:01",41,"( петухи могут какое-то время жить без головы",156686,null],[156691,"2026-08-12T19:48:11",41,"( потому он бегал и не кукарекал",151968,null],[156692,"2026-08-12T19:48:17",31,"А, точно. Типа сам сбежал?)/",156690,null],[156693,"2026-08-12T19:48:39",41,"( не, типа отрезали, но никто не слышал",156692,null],[156695,"2026-08-12T19:48:58",31,"На улице тем временем опять меняется погода, сгущаются тучи",151968,null],[156698,"2026-08-12T19:49:27",38,"// КАЛДУН ЕБУЧИЙ!",156695,null],[156699,"2026-08-12T19:49:32",38,"// ЖГИТЕ ЕГО!",151968,null],[156700,"2026-08-12T19:49:42",41,"Элиза Сразу подумает про \"зону тишины\", но зачем кому-то так морочиться. Или Это родная хозяйка не пришла на крик?",151968,null],[156703,"2026-08-12T19:49:58",41,"— Лени, как там у тебя?",151968,null],[156711,"2026-08-12T19:52:01",38,"— А чем он питался?\n Лени слушал ответы и сказал Элизе.\n— Думаю все же кто-то прошел мимо мисс или петух сбежал сам.",156480,null],[156712,"2026-08-12T19:52:16",55,"– Ну здравствуйте, мило. Можно задать вам пару вопросов?\nЭльф подходит к старику, выглядывает из-за плеча. \n– Нам уж очень нужно узнать обстоятельства одного дела. Не поможете?",156683,null],[156713,"2026-08-12T19:52:34",55,"/r d20+3 Убеждение",151968,null],[156715,"2026-08-12T19:52:42",41,"— Хм, Это не так.",156711,null],[156717,"2026-08-12T19:52:54",47,"Стоп!",156712,null],[156718,"2026-08-12T19:52:56",47,"Бля",151968,null],[156719,"2026-08-12T19:53:01",47,"Я стихотворение писал",151968,null],[156720,"2026-08-12T19:53:05",31,"- Пьтро не привередлив, но я не скупилась, откормила его лучшим ячменем",156711,null],[156721,"2026-08-12T19:53:11",47,"/сори",151968,null],[156722,"2026-08-12T19:53:12",41,"— Я нашла много следов, Будто за петухом активно бегали",156715,null],[156723,"2026-08-12T19:53:16",55,"/ Всё я помер. У меня уже голова кругом",151968,null],[156726,"2026-08-12T19:53:59",31,"Старик смотрит на тебя чутка затуманенным взглядом:\n\n-а? Чего надо?",156712,null],[156731,"2026-08-12T19:54:49",55,"/ @cirson жду тебя",151968,null],[156735,"2026-08-12T19:58:15",31,"Все ребята, я спать пойду, завтра продолжим. можете прямо с утра влетать, я с 6-00 по Москве уже буду готов вести)/",151968,null],[156744,"2026-08-12T20:00:04",41,"( спасибо! Споки!",156735,null],[156749,"2026-08-12T20:00:40",55,"/ Окей. Я конечно рано не проснусь, но постараюсь",151968,null],[156755,"2026-08-12T20:01:44",38,"// Спокойной ночи",156735,null],[156771,"2026-08-12T20:04:46",47,"- Увидишь сладкий сон, \nО богине прекрасной он, \nПреклони перед ней колени, \nОна станет лучшим что было, \nВ мрачных буднях жизни этой - спас мудрости с -д6",151968,null],[156772,"2026-08-12T20:04:57",47,"/из Спаса вычесть д6",151968,null],[156777,"2026-08-12T20:05:17",47,"/бошка не варит",151968,null],[156788,"2026-08-12T20:06:38",47,"Напевом произнесла Кейтлин, от её пальцев к лицу мужчины пролетел розовый туман, лицо мужчины раслабилось, разгладились, кажется он считает её близкой подругой",156771,null],[156791,"2026-08-12T20:06:47",47,"/почти уверен в успехе",151968,null],[156797,"2026-08-12T20:09:46",47,"/там ещё острота есть...",151968,null],[157758,"2026-08-13T05:26:30",31,"Дед плывет, разве что розовых сердечек не хватает в глазах",156788,null],[157760,"2026-08-13T06:28:27",47,"/что даже без Спаса? Жесть",151968,null],[157761,"2026-08-13T06:28:35",47,"/ну всё, он наш",151968,null],[157762,"2026-08-13T07:01:59",31,"то что у НПС есть имя и арт, еще не значит что унего есть спасы))/",157760,null],[157763,"2026-08-13T07:34:16",47,"- Дорогой друг, как долго я тебя не видела! - восклицает улыбаясь Кейтлин - помнишь свою старую подругу? Валерия я - подходит она ближе",151968,null],[157764,"2026-08-13T07:36:11",31,"- Лерочка, здравствуй дорогая, конечно помню. Как папа, как мама?",151968,null],[157765,"2026-08-13T07:36:29",31,"/старик осознает вашу разницу в возрасте/",151968,null],[157777,"2026-08-13T09:02:56",38,"Лени покачал головой и спросил еще раз у мисс.\n— Когда говорите у вас пропал Пьетро? И слышали ли вы что-то до исчезновения его?",151968,null],[157781,"2026-08-13T09:05:17",31,"- ночью. Он пропал ночью, вечером я насыпала ему зерна и пошла спать. Я крепко сплю, как говаривала моя бабушка, здоровый сон - это признак чистой совести. Ну и беруши я надеваю, это тоже помогает",157777,null],[157782,"2026-08-13T09:05:58",38,"— Значит ночью... Какие именно козни вам стоил ваш сосед?",157781,null],[157794,"2026-08-13T09:17:26",31,"Старушка заметно тушуется:\n\n- ну, он всегда говорит про меня гадости, и старается подобраться поближе, явно не с добрыми намерениями и только Пьетро его останавливал, он чуял злые мысли и всегда предупреждал меня, чтобы я успела выйти и послать старого козла Беппо куда подальше, он ведь трусливый, сразу убегает",157782,null],[157797,"2026-08-13T09:18:51",38,"— Понятно... Тогда мы скоро придем с новостями о вашем Пьетро... Всего доброго.\n Лени поклонился и сделав жест Элизе пошел к выходу и самому соседу.",157794,null],[157803,"2026-08-13T09:22:51",47,"- Ой, она замечательно, услышала о каком-то петухе Педро, или Пидро, так и не поняла, готова вывалить кучу денег какой-то сумасшедшей бабке за этот супной набор. А ты как? -",157764,null],[157805,"2026-08-13T09:24:10",31,"- да что я, я все со своими железками вожуся, уже скоро наверное доделаю прибор. Ежели не помру раньше, здоровье то уже не то...",151968,null],[157808,"2026-08-13T09:25:48",47,"- А что за прибор?",151968,null],[157810,"2026-08-13T09:28:19",31,"- это секрет (хитро улыбается)\n\n- но по секрету скажу, он оставит мое имя в истории!",151968,null],[157862,"2026-08-13T10:17:19",47,"- Что ещё расскажешь? Слышала тут соседка бегала твоя, причитала \"ой украли, ой украли\" Блаженная что-ли? Если украли причитаниями не помочь",151968,null],[157865,"2026-08-13T10:21:40",31,"- которая соседка? Я ничего не слышал, мне из за дурацкого петуха старой дуры напротив пришлось сделать полную звукоизоляцию, она его явно науськала на меня, все время орет, стоит мне рядом пройти. А уж как голосить начинает, когда я прибор тестирую... Не иначе она за мной следит да его булавкой тычет, чтобы орал и отвлекал меня",151968,null],[157867,"2026-08-13T10:24:34",47,"Кейтлин кивает с важным видом:\n- Может всё же расскажешь о приборе? Я честно никому никому не скажу. Но мне очень интересно - любопытствует она. Если что пиздить она не будет. Честно. Даже если там артефакт",151968,null],[157868,"2026-08-13T10:27:04",31,"Старик колеблется:\n\n- я не могу всего рассказывать, я же не патентовал его ишшо. Ну намекну, ты девочка вроде не глупая. У нас тут торговый город, все торговцы хотят грузы быстрее по морю возить, да бывает, погода подводит. А ежели они научатся ее усмирять, али менять? Все, больше ничего не скажу, и так разболтался...",151968,null],[157869,"2026-08-13T10:27:11",41,"( я смогу после 12 ти сори",151968,null],[157873,"2026-08-13T10:27:55",47,"- Ничего, но я в тебя верю, у тебя получится. Я... Могу помочь? - интересно",151968,null],[157878,"2026-08-13T10:30:10",31,"- нет, это мой проект и только мой. 40 лет работаю над ним, скоро закончу",151968,null],[157884,"2026-08-13T10:32:12",47,"- Что же. Тогда не мешаю. Удачи, дядя - и съебываюсь",151968,null],[157885,"2026-08-13T10:32:24",47,"/в принципе спокойно и мирно отсекли подозреваемого",151968,null],[158160,"2026-08-13T15:26:17",31,"Можешь об этом рассказать товарищам, которые все неподалёку, на улице/",151968,null],[158162,"2026-08-13T16:02:41",55,"/ ребят простите. Что тут произошло блин. С утра пораньше уже",151968,null],[158163,"2026-08-13T16:03:19",31,"Ну кому утро, а у кого уже и ночь почти)/",151968,null],[158164,"2026-08-13T16:03:49",55,"/ ну я не про то",158163,null],[158165,"2026-08-13T16:04:02",55,"/ а то что вы в 6 утра уже начали",151968,null],[158166,"2026-08-13T16:04:36",55,"/ как бы так попадать. Я ещё завтра в больницу лягу. Нда",151968,null],[158167,"2026-08-13T16:06:10",31,"Ну я ещё когда на квест собирал, писал что мне удобнее вести в первой половине дня по Москве, не просто же так))",151968,null],[158168,"2026-08-13T16:06:54",55,"/ ну я слепой. Буду тогда стараться раньше влетать.",158167,null],[158171,"2026-08-13T16:07:45",31,"Да ладно, основная движуха все равно позже стартует. Как видишь тут только Миша с утра отметился, допросил деда. Ты с ним был, тоже все слышал/",151968,null],[158182,"2026-08-13T16:11:42",55,"Эльф всё это время внимательно слушал. Уж то , что старик придумал прибор для управления погодой его знатно удивило. \n– Вот тебе и раз, а я думал вы колдун какой... Из-за того, что дом со стороны жутковато выглядит.  А вы такой умелый изобретатель, оказывается. Ну тогда прощайте, сиор. \n\nПарень учтиво поклонился и спустился, отправившись к остальным.",151968,null],[158255,"2026-08-13T17:10:08",31,"Если что, заявки принимаются/",151968,null],[158429,"2026-08-13T18:05:14",47,"Когда вышли на улицу и нашли своих, Кейтлин позволила всё рассказать тихому эльфу",151968,null],[159215,"2026-08-14T05:45:16",31,"Быстро однако двигаемся, да. Ребята, если нет идей или желания, вы мне пожалуйста так и скажите, я подкорректирую, может что то подкину и быстренько закончим. Мне очень не нравится стоять на месте//",151968,null],[159258,"2026-08-14T07:46:48",47,"/я жду пока мы обменяемся информацией.",151968,null],[159261,"2026-08-14T07:48:10",38,"// Ждём когда эльф все расскажет",151968,null],[159286,"2026-08-14T08:16:23",55,"/ну чё ему по сути пересказывать",159261,null],[159287,"2026-08-14T08:21:13",55,"По прибытию обратно к отряду , Вейн начал рассказывать что им удалось выяснить. \n– В общем, старик оказался безобиден. Но тут как говорится жаба гадюку... В общем считает , что соседка специально заставляет своего петуха кричать, раздражая его. А он изобретатель, сидит себе сутками в железках копается, машину для управления погодой мастерит.",151968,null],[159290,"2026-08-14T08:38:37",38,"— А я не выяснил, что закозни он \"строил\".\n Пальцами сказал Лени и продолжил.\n— Нужно понять в другом, кто убил петуха и зачем...",151968,null],[159291,"2026-08-14T08:46:56",31,"Мимо проходящий человек услышал посление слова и отреагировал:\n\n- ой, да кто бы не пришиб чертову птицу - он герой квартала. Чертова тварь всех достала своим криком, у любого спросите из местных жителей",151968,null],[159292,"2026-08-14T09:05:58",38,"— Так это он убил её?\n Повернулся Лени и спросил сразу же.",151968,null],[159293,"2026-08-14T09:09:39",31,"Прохожий:\n\n- вы меня спрашиваете? я ничего не знаю, просто говорю о том, что этого петуха тут не любили, сумасшедшая птица орала слишком громко и слишком часто. Нормальные петху ну утром прокричат, а этот в любой случайный момент мог заорать, всех достал. Да вон, загляните в в кабак сиоры ди Лупо на углу и у любог местного спросите",159292,null],[159294,"2026-08-14T09:13:30",38,"— Спасибо большое... Вы немного помогли нам...\n Лени поклонился и обратился к своим товарищам.\n— Давайте направился в этот кабак, чтобы собрать информацию.",159293,null],[159299,"2026-08-14T09:48:31",31,"//жду реакций от остальных, может есть другие идеи, и продолжим//",151968,null],[159305,"2026-08-14T10:05:26",55,"– Ну предложение в целом дельное. В расслабленной атмосфере, а тем более под градусом у любого язык развязывается. Так что кабак отличная идея. \nВыразил своё мнение Вейн. \n– Всё равно идей у нас больше нет.",159294,null],[159370,"2026-08-14T12:30:46",55,"/ ребят , если что с интернетом у меня сегодня плохо/",151968,null],[159371,"2026-08-14T12:51:49",47,"- У меня идей нет - честно сказала Кейтлин",151968,null],[159387,"2026-08-14T13:21:05",31,"через час-полтора отпишу вам кабак, пока работа не пускает//",151968,null],[159600,"2026-08-14T14:42:47",31,"Дойдя до кря квартала, вы замечаете здание кабака с поэтичным названием \"Под старым фонарем\". Фонаря, впрочем, вы не обнаруживаете. Прямо перед вами открывается дверь и здоровенный вышибала с лицом не обресеннемы интеллектом выбрасывает очевидно перебравшего клиента. Тот реагирует на такое обращение спокойно, очевидно, такое случается не в первый раз. Вам вышибала улыбается и делает приглашающий жест, что выглядит, честно говоря, даже страшнее чем его предыдущее действие.\n\n- милости прошу в нашу семейную тратторию, сиоры и сиоритты.\n\nВнутри вы видите прямо таки классический кабак, где дым коромыслом, в воздухе запах какого то прокисшего пива, кислой капусты и, неожиданно, апельсинов. Тут и там за столиками сидят выпивохи, кто то кричит, кто т ругается, в дальнем углу играют в карты, а посреди всего этого великолепия возвышается барная стойка за которой дирижирует всем этим бедламом крупная женщина с громовым голосом. Ее передник испачкан чем то жирным на вид, а лицо неоспоримо доказывает родство с вышибалой",151968,null],[159602,"2026-08-14T14:45:45",38,"Лени немного постоял и помахав рукой перед лицом прошел к барной стойке.\n— Здравствуйте, сиоритта. Мне бы хотелось спросить у вас пару вопросов по делу одного детективного агентства...",151968,null],[159604,"2026-08-14T14:48:20",41,"— Добрый день. Как можем к вам обращаться? Меня зовут Элиза, это Лени. Расследование.",151968,null],[159606,"2026-08-14T14:52:34",31,"очевидно, что обращение сиоритта польстило женщине. Она откидывает мокрую прялку волос и с пугающим кокетством отвечает:\n\n- Сиора ди Лупо. Но ты зови меня Франческа, милый. Что за агенство, и почему ко мне пришли? У нас спокойное семейное заведение, тут ничего противозаконного не происходит...\n\nЧто же время вы видите что в углу спокойного заведения начинается мордобой",159602,null],[159607,"2026-08-14T14:52:55",31,"Хочешь бросить на расследование? Что ищешь?//",159604,null],[159608,"2026-08-14T14:56:53",38,"Лени открывает свою книгу и продолжает.\n— Франческа, мы хотели бы спросить про сиору ди Бьяко и её петуха Пьетро. Нам сказали, что он мешал всем соседям... Мне бы хотелось узнать подробности...",159606,null],[159609,"2026-08-14T15:00:04",31,"- крикливая тварь. И я не про петуха сейчас. Старуха совсем поехала, заявляет всем что петух у нее волшебный и стоит только кому слово против сказать, так начинается крик. Честно говоря, я не удивлена что кто то свернул петуху шею да и отправил в бульон, где ему и место",159608,null],[159612,"2026-08-14T15:14:35",41,"( это фраза перса",159607,null],[159613,"2026-08-14T15:14:51",31,"Сорян, недопонял/",159612,null],[159614,"2026-08-14T15:16:42",31,"- а что, это психованная вас наняла найти ее петуха? Вот уж не подумала бы что серьёзные люди поверят ее росскозням.",151968,null],[159615,"2026-08-14T15:17:42",38,"— Да все равно мы не верим этом, просто интересно кто это сделал и где труп. Вы же понимаете, что это очень простые деньги для нас и это абсурдное дело, Франческа.",151968,null],[159616,"2026-08-14T15:17:46",41,"— У нас есть заказ. Вы знаете что-то о ней и её недоброжелателях?",159614,null],[159617,"2026-08-14T15:18:00",41,"Элиза звучала холодно",151968,null],[159618,"2026-08-14T15:19:26",38,"// И я не старался соблазнять эту владелицу табака",151968,null],[159620,"2026-08-14T15:23:47",31,"О старухе то? Да что про неё знать то? Ну ходят слухи, что куролесила по молодости, потом замуж выскочила и стала вроде как респектабельной дамой, а потому у нее крыша поехала, вот и все. Не думаю что у неё естьб прямо недоброжелатели, она же типа наша городская сумасшедшая, своего рода достопримечательность. Что до ее волшебного петуха, так да, он любил поорать, но я скорее поверю что старуха сама на него беду навлекла, когда про его волшебные способности говорила каждому встречному",159616,null],[159621,"2026-08-14T15:24:52",31,"Я знаю, просто отыгрываю болтливую трактирщицу, котофо понравилось обращение как к юнной деве. Вежливость решает///",159618,null],[159623,"2026-08-14T15:25:29",41,"— Вы говорили, что она вышла замуж, но на нас не знакомили с синьором ( забыла фамилию)",159620,null],[159624,"2026-08-14T15:25:56",38,"// Просто как факт скажу, что у меня в жизни проблемы с иностранными обращениями и я вот недавно сэр, мисс, мистер и леди выучил, а тут итальянские...",151968,null],[159625,"2026-08-14T15:26:00",31,"- так старый Ди Бьякко помер года три назад. Тогда она петуха примерно и завела",159623,null],[159626,"2026-08-14T15:26:21",31,"Не просто итальянские, я их еще и исказил))//",159624,null],[159627,"2026-08-14T15:26:23",38,"Лени начал записывать все что говорили.",151968,null],[159628,"2026-08-14T15:26:29",38,"// В этом и проблема",159626,null],[159629,"2026-08-14T15:26:41",41,"( я и искажения ещё забываю",159626,null],[159630,"2026-08-14T15:26:44",31,"//для антуража//",159628,null],[159631,"2026-08-14T15:26:49",41,"( потому говорю в оригинале",151968,null],[159633,"2026-08-14T15:26:56",31,"Говори как удобно//",151968,null],[159634,"2026-08-14T15:27:08",31,"Вы же иностранцы, вам можно ошибиться//",151968,null],[159635,"2026-08-14T15:30:00",38,"— И тогда вопрос еще про эту улицу, вы знаете чем занимается этот самый \"сосед\" сиоры ди Бьяко?",159625,null],[159636,"2026-08-14T15:32:26",31,"- Беппо Кольбт что ли, главный враг ее? Да боги ведают, он скрытый дед, только и говорит что скоро разбогатеет на своем изобретении. Лет 30 уже так говорит, я совсем девчонкой была а он уже тогда был с прибабахом.  \n\nНаклоняется на стойкой и говорит вполголоса, словно готова поведать тайну:\n\n- я, рюгрешным делом, думаю что когда то у Беппо и старухи что то было, ну нельзя так ненавидеть человека, которого никогда не любил...",159635,null],[159637,"2026-08-14T15:34:15",38,"— Я... возьму это на заметку...",159636,null],[159638,"2026-08-14T15:35:33",31,"Франческу окликает другой посетитель и она извинившись отходит от вас",151968,null],[159639,"2026-08-14T15:36:57",31,"Киньте на внимание что ли/",151968,null],[159640,"2026-08-14T15:37:17",38,"— Так... Нужно сообщить об этом нашему \"боссу\" и еще как-то решить это...",151968,null],[159641,"2026-08-14T15:37:27",38,"/r 1d20+2",159639,null],[159643,"2026-08-14T15:37:32",38,"// АААА",151968,null],[159644,"2026-08-14T15:37:57",31,"Ох, сейчас долго придётся писать походу//",151968,null],[159645,"2026-08-14T15:47:06",31,"До твоих ушей доносится:\n\n- скоро верну, скоро мне попрёт, Фреддо, обещаю\n\n- я это уже слышал, и от тебя, и от твоего брата. Долг только растёт, а вы так и не научились лошадей выбирать. Срок тебе до завтра.\n\n- ну пожалуйста, Фреддо, поверь, мы точно отыграемся, у нас есть как бы, секретное оружие...\n\n- не неси чушь, лучше неси деньги. Или завтра ваша лавка сгорит к демонам.\n\n- в последний раз поверь, Фреддо, на нашей стороне будет \"неразборчиво\", мы точно знаем что победит Гиацинт. Если нет, то я сам сожгу лавку!\n\n- ты идиот, как и твой брат. Гиацинту не добежать до финиша, не ть что выиграть. Сам себя закапываешь в могилу. Ладно, только ради памяти твоей покойной матушки.\n\nТы оглядываешься и видишь что оазговаотвали двое мужчин в тёмном углу. Один, очевидно, Фреддо, лощёный франт, его свита состоит из двух громил, второй из говоривших им не уступает ростом и габаритами, но бойцом не выглядит, скорее просто крупный мужик, который работает руками. Их разговор закончен и неизвестный мужик, имени которого ты не знаешь, с довольным лицом пок даёт кабак",151968,null],[159646,"2026-08-14T15:47:57",31,"Ваши действия?",151968,null],[159647,"2026-08-14T15:48:25",41,"( это слышит только Лени ?",151968,null],[159648,"2026-08-14T15:48:40",31,"Ну он бросал, так что да/",159647,null],[159649,"2026-08-14T15:49:00",31,"Ты соглв сылашать отголоски со своей пассивкой/",151968,null],[159650,"2026-08-14T15:49:14",38,"— Как зовут второго владельца кабака?\n Спрашивает Лени у Элизы и говорит это так, чтобы вопрос могли услышать кто-то рядом.",151968,null],[159651,"2026-08-14T15:49:33",31,"Ты у кого спрашиваешь?/",159650,null],[159652,"2026-08-14T15:50:08",38,"// Дописал",151968,null],[159653,"2026-08-14T15:53:10",31,"На твой вопрос отвечает сидящий за стойкой мужичок с крыжкой пива:\n\n- так тут Франческа хозяйка, как ее муж преставился, так она с сыновьями тут и рулит. Всех в кулаке держит, бой-баба",159650,null],[159654,"2026-08-14T15:55:39",38,"Лени указывает рукой с пером в руке в сторону угла.\n— А это получается...",159653,null],[159655,"2026-08-14T15:57:16",31,"Мужик переводит взгляд, в дит Фреддо и на глазах трезвеет:\n\n- это сиор Фреддо Треви, я не думаю что... Мне пора\n\nСваливает, оставив на стойке монеты за пиво",159654,null],[159656,"2026-08-14T15:58:17",38,"— Что с ним?\n Лени переводит взгляд на Элизу.\n— Ты что-то поняла? Просто я не так хорош в чтении людей...",159655,null],[159657,"2026-08-14T15:58:48",41,"/r d20+2 проницательность Элизы",151968,null],[159659,"2026-08-14T15:58:59",41,"— Я тоже ничего не поняла, правда",151968,null],[159660,"2026-08-14T15:59:28",41,"( блять",159650,null],[159661,"2026-08-14T15:59:33",41,"( сори",151968,null],[159662,"2026-08-14T15:59:44",41,"— Его имя… я естественно не знаю",151968,null],[159663,"2026-08-14T16:00:26",38,"— Ха... Просто я услышал часть разговора и мне нужно понять кто этот Фреддо...\n Признался Лени и посмотрел, где хозяйка",151968,null],[159665,"2026-08-14T16:03:48",41,"— почему? Что в нём такого ?",159663,null],[159666,"2026-08-14T16:04:08",38,"— Да так... Кое-что заметил...",159665,null],[159668,"2026-08-14T16:04:42",41,"— Ты не хочешь говорить об этом здесь ? Если да, то давай выйдем",151968,null],[159669,"2026-08-14T16:06:34",38,"— Сначала нужно сообщить хозяйке",159668,null],[159670,"2026-08-14T16:06:47",41,"— Ладно",159669,null],[159671,"2026-08-14T16:06:57",41,"/r d20+2 а где ?",151968,null],[159673,"2026-08-14T16:07:06",41,"( поиск хозяйки",151968,null],[159674,"2026-08-14T16:07:34",47,"/Ойо",151968,null],[159675,"2026-08-14T16:07:43",47,"/ладно, тогда пока дальше тоже без меня",151968,null],[159677,"2026-08-14T16:08:21",31,"Хозяйка трещит с очередным посетителем на другом конце стойки",159673,null],[161623,"2026-08-15T15:32:27",55,"/ так , меня ещё на три весёлые послать не собираются? Сегодня отвечу если вдруг",151968,null],[161637,"2026-08-15T15:41:54",31,"Нет, не собираются) можешь влететь в разговор, почитай что понаписали и отпишись, что хочешь сделать//",161623,null],[161639,"2026-08-15T15:43:09",31,"В выходные я сам мало тут могу сидеть, так что никого не тэгаю даже//",151968,null],[161938,"2026-08-15T18:27:54",47,"/товарищи, проблемы в реале буду отвечать очень редко. Я бы не хотел вас оставлять, но видимо вынужден. Кейтлин, если можно, лучше вывести при помощи того, что типо уважаемого человека освободили и она заболтала ему зубы. Пока просто заболтала /",151968,null],[161955,"2026-08-15T18:49:09",31,"В кабак забебает молодой табакчи, которого вы видели ранее в конторе сыщика. Тот находит Кейтлин, и передает ей записку. Ты читаешь:\n\n\"Госпожа Кейтлин, ситуация с господином Шалье разрешилась куда быстрее чем я ожидал. Я уже переговорил с ним по поводу вашего ученичества, и он ожидает вас в Ремесленном квартале, адрес прилагаю. За сим я освобождаю вас от контракта со мной и желаю успехов в учебе. Буду рад сотрудничеству в будущем. С уважением, Неро Феллино.\"",161938,null],[161956,"2026-08-15T18:49:54",31,"Все, Миша, вывел тебя, если что, возвращайся как будет возмодность. +100 опыта себе запиши//",161938,null],[161960,"2026-08-15T18:52:01",47,"/спасибо",151968,null],[161961,"2026-08-15T18:52:06",47,"/опыт не надо. Не заслужил",151968,null],[162672,"2026-08-16T16:31:19",55,"/ Оз сколько вы тут настрочили. Голова кругом",151968,null],[162677,"2026-08-16T16:36:27",31,"Читай, изучай и приступай, ничего сильно сложного тут нет///",151968,null],[162712,"2026-08-16T17:06:12",55,"Вейн это время пока только слушал всё о чём говорили его товарищи. \n– Не нравится мне этот Фреддо... Давайте и правда выйдем и обсудим всё , что в итоге выяснили.",151968,null],[162748,"2026-08-16T17:55:22",31,"//Эльза нас покидает путём редкона. Просто представим, что ее не было в этой истории//",151968,null],[162749,"2026-08-16T17:55:47",31,"@FelixFadeev @STR_AllXSeeV вы остались вдвоём парни, надеюсь доведете дело до конца//",151968,null],[162750,"2026-08-16T17:59:38",55,"/ весело",151968,null],[162751,"2026-08-16T18:01:29",31,"Всякое случается. Да и квест такой что и в одиночку можно закрыть))",151968,null],[162754,"2026-08-16T18:12:26",38,"// А что с Элей?",162748,null],[162755,"2026-08-16T18:12:45",41,"( не тяну 4 перса на соц квестах",162754,null],[162756,"2026-08-16T18:12:50",41,"( сори",151968,null],[162757,"2026-08-16T18:12:52",38,"// А...",151968,null],[162758,"2026-08-16T18:12:56",38,"// Понятно",151968,null],[162759,"2026-08-16T18:12:59",31,"//попросила ее отпустить, слишком много квестов/",162754,null],[162760,"2026-08-16T18:13:29",41,"( у меня Элиза более боевой перс, решила именно её освободить",151968,null],[162799,"2026-08-16T20:16:13",38,"Лени посмотрел на эльфа и вздохнув сказал.\n— Давай тогда сразу к нашему \"Боссу\"...\n На этом Лени встал со стула и изменив одежду на деловой костюм пошел в сторону выхода.",162712,null],[162800,"2026-08-16T20:18:25",55,"– Хорошо, пошли. \nВейн пошёл за ним следом. \n– Всё равно пока мы особо ничего сделать и не сможем. Больше конкретных подозреваемых нет, а информацию больше узнать не от кого.",162799,null],[162801,"2026-08-16T20:23:31",38,"— Нужно просто сообщить о всем, что мы узнали и предупредить \"босса\" об завтрашнем будущем...",162800,null],[162802,"2026-08-16T20:31:55",55,"– Ты о каком таком будущем говоришь?\nСпросил эльф, когда они уже взяли курс на агенство.",162801,null],[162803,"2026-08-16T20:33:31",38,"— Расскажу у детектива...\n Ответил Лени, тоже идя в его сторону.",162802,null],[163299,"2026-08-17T05:36:29",31,"Без особых приключений вы добираетесь до конторы детектива. Толстый табакси пребывает в благодушном настроении, угощает вас кофе и после приветствия выжидательно смотрит на вас, ожидая ваших слов",162803,null],[163318,"2026-08-17T09:05:21",38,"Лени открывает книгу и начал говорить все что записал.\n— Мы узнали, что у сиоры Ди Бьяко есть некоторые отклонения здравого рассудка, после смерти её супруга. Она завела петуха Пьетро сразу после смерти супруга и не давал покоя никому из соседей на улице. Она указала на своего соседа, но он занимается последние четыре года одним изобретение и от владелицы Кабака на углу улицы мы узнали, что у него тоже не все удачно. Сосед сиоры ди Бьяко создаёт устройство меняющее погоду. Так же большая часть жителей рада, что петуха Пьетро больше нету.\n Сам петух кричал на каждого прохожего, как собака и похоже он имел повышенный страх и кричал из-за этого или что-то такое.\n Теперь есть новость о которой я узнал сидя в Кабаке... Фреддо заключил с кем-то пари о победе Гиацинта, если же гиацинт проиграет, то Фреддо сожжёт лавку. У этого человека также был брат. К сожалению я не знаю кто именно был им, но он занял у Фреддо большую сумму долга...\n После этого Лени закрыл её ну и выдохнул сказал.\n— Это все что мы узнали за последнее время...",163299,null],[163320,"2026-08-17T09:17:57",31,"- столкнулись с Фреддо Треви? Не уверен, что он имеет какое то отношение к пропаже петуха, не его уровень петухов воровать у старушек. Он представитель довольно влиятельного семейства с так сказать, мутной историей доходов. Конкретно он в семье букмекер, обычная схема - загонять человека в долги и отжать все что есть. Не запомнили, случайно, с кем он общался? Видимо, очередной лудоман, который все решил поставить на старую лошадь с высокими котировками. Но по мне, даже сумасшедший не стал бы ставить на Гиацинта, это старый конь, которого от мыловарни спасет только статус чемпиона прошлых лет. Но он слишком стар, и ставить на него сейчас будет лишь ненормальный, либо тот у кого есть какая то инсайдерская информация. Ну или прорицатель какой, что увидет завал всех фаворитов. Но что то сомневаюсь что тот кто занимает деньги у Фреддо может быть таким прорицателем",163318,null],[163322,"2026-08-17T09:20:13",38,"— Поэтому это все что мы узнали и вернулись к вам...\n Лени немного разлёгся в кресле и протерев глаза продолжил.\n— Вообще я не думаю, что уже спустя полдня и больше можно найти петуха... Он же уже сварился или съеден...",163320,null],[163325,"2026-08-17T09:25:49",31,"- ага, или улетел. Но нам платят за эти поиски. Вообще, насколько я знаю, петухов обычно режут еще птенцами, живых оставляют немногих, только на развод для куринной стаи. Соответственно, и останки петуха, ну там перья или более крупные кости, будут бросаться в глаза. Можно пройтись по задворкам квартала, поискать там следы. Работа грязная, но бывает необходимой. Вы удивитесь сколько всего может рассказать о жителях дома его мусор.",163322,null],[163326,"2026-08-17T09:27:18",38,"Лени немного задумался и вспомнив как выглядел его прошлый дом в мусоре из бумаги вздрогнул.\n— Соглашусь... Получается нужно найти хотя бы что-то это этого петуха и показать вам, верно?",163325,null],[163335,"2026-08-17T09:31:34",31,"- ну, вообще сиора Ди Бьякко просила наказать виновника и утверждала, что только очень плохой человек мог бы покусится на невинную птичку.  То есть да, задача минимум - найти петуха либо его останки, в задача максимум - накопать грязи на похитителя. Я конечно не делю мир на тех кто любит петухов и тех кто из обижает, но вот с тем что на каждого можно найти грязь или компромат я согласен. Живу с этого",163326,null],[163341,"2026-08-17T09:36:01",38,"Лени вздохнул и открыв книгу сказал.\n— Надо будет узнать тех, кто были ночью у дома сиоры Ди Бьяко, ведь именно ночью кто-то и убил петуха...",163335,null],[163342,"2026-08-17T09:37:13",31,"- скажите, а почему вы не используете другие методы, кроме беседы? Если петуха унесли, могли же остаться следы?",151968,null],[163344,"2026-08-17T09:37:57",38,"// Я уже забыл, что нашла Эля ...",151968,null],[163345,"2026-08-17T09:38:26",31,"//следы в вольере, много следов тяжёлых сапог",163344,null],[163347,"2026-08-17T09:40:07",38,"— Мы нашли... Следы в вольере петуха в виде погони и тяжёлые следы сапог... Я к сожалению не сыщик или кто-то такой в этой сфере...\n Лени продолжил прочитывать книгу, чтобы понять, что он мог не рассказать.",163342,null],[163350,"2026-08-17T09:41:26",31,"- если есть след, значит он куда то может привести, это ведь логично?",151968,null],[163351,"2026-08-17T09:42:25",31,"- если вы сами не в ладах с чтением следов, то может поискать ткх, кто умеет, или специализируется на этом? Охотники может, или ещё кто",151968,null],[163353,"2026-08-17T09:43:35",38,"Лени немного оторвался от книги и посмотрев на эльфа долгим взглядом сказал.\n— Не думаю, что он похож на следопыта... Да и я не думаю, что нам хватит бюджета на это...",151968,null],[163354,"2026-08-17T09:44:29",31,"- умение договариваться в чести в этом городе. Я уже говорил, тут хорошо работает принцип: ты мне - я тебе",163353,null],[163359,"2026-08-17T09:47:54",38,"У Лени немного дернулся глаз и он сказал.\n— Да не понимаю я вашу эту систему... Ха... Ну почему меня сюда отправили...\n Лени разлёгся на кресле и продолжил.\n— В итоге нам нужно найти крылья и вернуть их вам, если удастся то и самого преступника тоже.... Верно?",163354,null],[163362,"2026-08-17T09:49:34",31,"- верно",151968,null],[163364,"2026-08-17T09:49:53",38,"— Сколько вы нам заплатите за это?",163362,null],[163365,"2026-08-17T09:50:39",31,"- Ну, вас осталось двое, поделите 100 зм на двоих значит",163364,null],[163366,"2026-08-17T09:52:30",38,"— Понятно...\n Лени с трудом встал с кресла и потянувшись изменил наряд на мундир без звёзд и наград.\n— Тогда идём играть в сыщиков и следопытов... Вейн, пойдем...\n Лени направился к выходу",163365,null],[163368,"2026-08-17T09:53:41",31,"@FelixFadeev Феликс, скажи пожалуйста, мне ждать от тебя игры или по быстренькому уже отпустить Дениса?",151968,null],[163547,"2026-08-17T11:53:43",55,"Отпускай его",163368,null],[163548,"2026-08-17T11:54:22",31,"то есть тебя не ждать? ок, спасибо за ответ//",163547,null],[163549,"2026-08-17T11:55:04",55,"/ просто я стараюсь попасть конечно, но не успеваю в тот момент, когда играете",151968,null],[163553,"2026-08-17T11:56:29",31,"@STR_AllXSeeV Денис, партия развалилась к сожалению, если хочешь, можем доиграть, хотя социалка в одного это то еще удовольствие)) в общем, решать тебе, как единственному активому игроку)//",151968,null],[163554,"2026-08-17T11:56:54",38,"// ПАРТИЯ БУДЕТ ДОИГРАНА!",163553,null],[163555,"2026-08-17T11:57:49",31,"ну тогда жду заявок, пиши все тчо в голову придет, отыграем до конца//",151968,null],[163560,"2026-08-17T12:06:20",38,"// Мне нужно четкое представление об улице на которой живет наша сумасшедшая заказчица и наверное пока все",151968,null],[163564,"2026-08-17T12:08:24",31,"сейчас схему нарисую//",163560,null],[163575,"2026-08-17T12:15:53",31,"Схема той части улицы где живет клиентка. Красный - дом клиентки, зеленый - дом ее соседа-изобретателя, желтые - просто жилые дома, вы не знаете кто там живет. синий - мясная лавка, серый - лавка зеленщика, фиолетовый - кабак",151968,null],[163579,"2026-08-17T12:17:07",38,"Придя обратно на улицу и изучив её Лени решил попытать удачу на самом простом варианте и направился в мясную лавку, чтобы узнать не могло ли счастье упасть на него с небес.",151968,null],[163592,"2026-08-17T12:21:10",31,"Перед тобой мясная лавка братьев Рино. не особо уютное заведение, в нос бьет резкий металлический запах крови. Тебя встречает неулыбчивый громила с тесаком, который что то (или кого то) разделывает на колоде. Второй из братьев занят варкой какого то мяса позади брата и на тебя внимания не обращает\n\n- чего надо? \n\nтебя встречают без улыбки, видимо про клиентооринтированность тут не слышали",151968,null],[163595,"2026-08-17T12:22:06",38,"// Сразу спрошу. Перья тут случайно или нет?",163592,null],[163599,"2026-08-17T12:22:43",31,"нейронка так нарисовала. но можешь и сам спросить//",163595,null],[163608,"2026-08-17T12:26:20",38,"Лени осматривает заведение взглядом, убрав улыбку и стараясь показать усталость, говорит.\n— Я тут чтобы узнать по делу одной сумасшедшей соседки, она уже всем ужи прожужжала про своего петуха и я хотел бы узнать не вы ли его убрали?\n  Вместе с этим Лени попытался посмотреть на сапоги мясников.",163592,null],[163611,"2026-08-17T12:26:59",31,"ты не стесняйся кидать кубы, на внимание, проницательность или что то еще. мне не сложно это описывать.//",163608,null],[163613,"2026-08-17T12:27:37",38,"/r 1d20+1+1 Внимание/Восприятие",151968,null],[163616,"2026-08-17T12:27:55",31,"- а мы тут причем? мы не забойщики, мы с тушами работаем, на кой черт нам тот петух?",163608,null],[163622,"2026-08-17T12:29:32",31,"сапого и братьев большие и тяжелые, такие вполне могли ооставить следы в вольере. а еще тебе в нос бьет запах куринного супа, младший из братьев как раз открыл кастрюлу чтобы премешать варево",163614,null],[163628,"2026-08-17T12:31:06",38,"Лени помахал книгой перед лицом, чтобы убрать запах и продолжил.\n— Как раз хотел бы сказать, что вам передают спасибо за то, что вы его убили...\n Лени достает золотую монету и продолжает.\n— Если это вы его убили, то могу дать вам эту золотую...",163622,null],[163630,"2026-08-17T12:32:28",31,"Мужик смотрит на монету с вожделением, но в голове у него есть еще сомнение:\n\n- кто передает то?",151968,null],[163632,"2026-08-17T12:33:42",38,"— От меня и большей части людей из кабака...",163630,null],[163635,"2026-08-17T12:34:52",31,"убежденте кинь, или обман//",163632,null],[163638,"2026-08-17T12:35:21",38,"/r 1d20+1 Обман",163635,null],[163640,"2026-08-17T12:35:27",38,"// Так и знал...",151968,null],[163641,"2026-08-17T12:36:14",31,"увы, не прошел//",151968,null],[163644,"2026-08-17T12:36:41",31,"- что то ты мелешь хрень какуто. ты либо покупоай мясо, либо вали нахрен отседова",151968,null],[163647,"2026-08-17T12:37:33",38,"— Тогда мне бы за эту золотую вон ту кастрюлю супа или хотя бы перья за петуха в его приготовлении...",163644,null],[163648,"2026-08-17T12:40:17",31,"услышав про суп, громила аж с лица спал:\n\n- суп не дам, это наш, эта, семейный рецепт. на свои перья, тока лвали отсюда\n\nПротгивает тебе пучок перьев, просто хваатет с колоды и отдает тебе пучком, там в основном белые, но есть и пара темных, с зеленоватым отливом, все уделаны в крови",163647,null],[163653,"2026-08-17T12:45:56",38,"Лени подкидывает золотую монету мясникам и взяв перья говорит.\n— До свидания, дорогие друзья (На великаньем)\n И покидает лавку размышляя над тем не спросить ли у самой сиоры ди Бьяко не те ли это перья.\n— Все равно пойду.",163648,null],[163655,"2026-08-17T12:46:52",31,"не жалеешь старушку то? а ну как инфаркт?))//",163653,null],[163657,"2026-08-17T12:47:25",38,"// Если она помрет мне будут благодарны все жители улицы, ну а на кота мне немного пофиг",163655,null],[163659,"2026-08-17T12:47:34",38,"// К сожвлению",151968,null],[163661,"2026-08-17T12:49:16",31,"ладно, ты проходишь чуток по улице, и оказваешься перед домом старушки. она копается у себя в саду, замечает тебя и подходит к оградке:\n\n- ох, вот и вы! Есть ли новости о моем малыше, моем защитнике Пьетро?!",151968,null],[163664,"2026-08-17T12:50:03",38,"Лени начинает смотреть вниз и говорит немного печальным тоном.\n— У меня есть две новости... Хорошая и плохая... Какую будете слушать первой?...",163661,null],[163667,"2026-08-17T12:51:09",31,"- о святые небеса... начинайте с плохой...",151968,null],[163672,"2026-08-17T12:51:43",38,"Лени помолчал и изменив наряд одежды на деловой костюм ответил.\n— Он... Мертв...",163667,null],[163680,"2026-08-17T12:53:09",31,"Старушка оседает на землю, тихо рыдает:\n\n- я знала, нет чувствоала, что он не мог меня бросить... как это случилось, кто убил моего невинного малыша, кто это чудовище?!",151968,null],[163688,"2026-08-17T12:54:06",38,"Лени начал еще сильнее опускать голову и продолжил.\n— К сожалению я не нашел убийцу... Я нашел только остатки его перьев...\n Лени достал их и продолжил.\n— Это зеленое перо, ведь его?",163680,null],[163691,"2026-08-17T12:54:38",31,"- даааа... (завывание)",151968,null],[163697,"2026-08-17T12:56:48",31,"- где было перо? кто это сделал?",151968,null],[163698,"2026-08-17T12:57:34",38,"// Тут есть сточные канавы или куда сбрасывают мусор?",151968,null],[163702,"2026-08-17T12:58:47",31,"мусорные баки, периодически телеги приезжают и забирают. жидкие отходы - в канавы за домами\\\\",163698,null],[163711,"2026-08-17T12:59:41",38,"— Тогда и хорошей новости так таковой и нету...\n Ответил Лени и немного подумав ответил.\n— Я нашел его когда шел обратно на улицу около одной из сточных канав за одним из домов... Я хотел заглянуть сначала к вам, чтобы еще раз осмотреть место, но обнаружил это...",151968,null],[163714,"2026-08-17T13:00:24",31,"кидай обман))/",151968,null],[163716,"2026-08-17T13:00:37",38,"/r 1d20+1 Обман прошу",151968,null],[163727,"2026-08-17T13:03:27",31,"Старушка рыдает, прижимая к груди перо. Она тебя даже не слушала похоже, растворившись в своем горе.\n\n- Ох Пьетро, Пьетро, на кого же ты меня покинул.. я никогда не узнаю теперь, кто же то чудовище, чо отняло тебя у меня, малыш,,,\n\nСмотрит на тебя заплакаными глазами:\n\n- спасибо вам, молодой человек. я отправлю чек в вашу контору...\n\nСгорбившись, она уходит в дом",151968,null],[163730,"2026-08-17T13:04:03",38,"// Сука мне не хочется теперь отыгрывать лицемера, но придется...",151968,null],[163737,"2026-08-17T13:05:34",38,"Лени стоит еще пару минут и поклонившись направляется в сторону агентства. Весь путь парень молчал.",163727,null],[163766,"2026-08-17T13:12:45",31,"Сыщик встречает тебя в приподнятом настроении, очевдно, чем от старушки уже пришел и порадовал старого табакси.\n\n- оличная работа молодой человек, я очень вами доволен! Я только не понял из записки сиоры ди Бьякко, о чем сожалеет она? что про невозможности призвать виновника к ответу. Не поясните?",163737,null],[163780,"2026-08-17T13:16:15",38,"Лени вздохнул и в прямом смысле лежа расположившись на диване отвечает.\n— Убийца являются два брата мясника в лавке на той же улице, я просто решил проверить самую очевидную вещи и удача дала мне шанс. Они предположительные убийцы, ведь в вольере были тяжелые следы сапог и вот результат... Они довольно полные... Извините за это...\n Парень положил свою книгу под голову и продолжил.\n— Либо они готовили себе обед из другого петуха или так реально совпали обстоятельства... Я не знаю...",163766,null],[163785,"2026-08-17T13:17:28",31,"- хм, хм, а почему же вы не сказали об этом клиентке? она бы хотела бы знат правду? зачем вы ей солгали?",163780,null],[163791,"2026-08-17T13:18:38",38,"— А она бы что сделала? Узнай она об этом, то сама бы пошла к этим парням и возможно померла бы от них или получила рану... У меня есть немного ума, чтобы предположить ближайшие сценарии об этом...",163785,null],[163803,"2026-08-17T13:22:29",31,"- она ведь хотела наказать их, найти что то, чтобы их упечь за решетку. впросем, это уже частности, раз клиент решал что задание выполнено, значит так оно и есть. Правда, сегодня мы выступили скорее как психлоги, чем как детективы.",163791,null],[163804,"2026-08-17T13:23:17",31,"у в целом, квест закрыт)) ща напишу Харду, уточню по наградам, а иебе если хочешь могу рассказать в чем была суть истории))//",151968,null],[163805,"2026-08-17T13:23:33",38,"// Давай в лс",163804,null],[163853,"2026-08-17T13:56:25",31,"Старый табакси, выдав свою сентенцию, достает из стола мешочек с золотом и передает его Лени\n\n- чтоже, вот ваш честный заработок. Ежели будет необходимость в работе, обращайтесь, мне всегда нужны грамотные агенты",151968,null],[163855,"2026-08-17T13:57:39",31,"@STR_AllXSeeV +100 золота и +500 опыта, 300 из них за закрытие квеста, 200 за отыгрыш\n\n@FelixFadeev тебе 100 опыта, мне понравился твой отыгрыш, но к сожалению полностью тебя оценить не могу, вклад маловат",151968,null],[163856,"2026-08-17T13:58:39",31,"Все етаки жалко что квест по сути закончился не начавшись, я много чего сюда напихал, что не вскрылось. Можете еще пригодится, если продолжу писать//",151968,null],[163867,"2026-08-17T14:05:28",38,"Лени посмотрел на мешок золота и взяв его лежа сказал.\n— Тогда...\n Парень немного привстал и полноценно встав на ноги сказал.\n— Увидимся с вами в будущем...\n Лени изменил наряд на саван и пошел в сторону выхода с мешком золота.",163853,null],[163943,"2026-08-17T14:32:52",55,"Я понимаю. Совпало всё неудачно",163855,null],[167908,"2026-08-22T19:37:14",47,"/жалко(",151968,null]]);
